changeSet.sql:
-- Guarded: the changeset is declared irreversible (see the rollback element), so a rollback that stops short of
-- catalog_collections leaves this constraint behind, and the forward re-apply must not fail on it.
DO $guard$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_constraint k
                    WHERE k.conrelid = 'nexus.catalog_collections'::pg_catalog.regclass
                      AND k.conname = 'catalog_collections_tenant_name_model_uq') THEN
        ALTER TABLE nexus.catalog_collections
            ADD CONSTRAINT catalog_collections_tenant_name_model_uq UNIQUE (tenant_id, name, embedding_model);
    END IF;
END
$guard$;

-- The one naming function. Pure: text in, text out.
CREATE OR REPLACE FUNCTION nexus.partition_name(
    p_parent_name text,
    p_model       text,
    p_tenant      text DEFAULT NULL
) RETURNS text
LANGUAGE plpgsql
STABLE
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_name text;
BEGIN
    IF p_parent_name IS NULL OR p_model IS NULL THEN
        RAISE EXCEPTION 'nexus.partition_name: a parent name and a model are required (parent %, model %)',
            p_parent_name, p_model
            USING ERRCODE = 'null_value_not_allowed';
    END IF;
    v_name := pg_catalog.regexp_replace(p_parent_name, '_new$', '')
        || '_m'
        || pg_catalog.left(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_model, 'UTF8')), 'hex'), 8);
    IF p_tenant IS NOT NULL THEN
        v_name := v_name
            || '_t_'
            || pg_catalog.left(pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(p_tenant, 'UTF8')), 'hex'), 16);
    END IF;
    IF 63 < pg_catalog.octet_length(v_name) THEN
        RAISE EXCEPTION 'nexus.partition_name: % is % bytes, over the 63-byte identifier limit', v_name, pg_catalog.octet_length(v_name)
            USING ERRCODE = 'name_too_long';
    END IF;
    RETURN v_name;
END
$fn$;

-- The value of a single-value LIST partition bound (FOR VALUES IN ('x')), unquoted; NULL for any other bound.
CREATE OR REPLACE FUNCTION nexus.partition_bound_value(p_rel regclass) RETURNS text
LANGUAGE sql
STABLE
SET search_path = pg_catalog, pg_temp
SET standard_conforming_strings = on
AS $fn$
    SELECT pg_catalog.replace(m[1], '''''', '''')
      FROM pg_catalog.pg_class c,
           LATERAL pg_catalog.regexp_match(pg_catalog.pg_get_expr(c.relpartbound, c.oid), '^FOR VALUES IN \(''(.*)''\)$') AS m
     WHERE c.oid = p_rel
$fn$;

-- Refuses any parent but the four the layout is built for, and any of those that is not partitioned
-- BY LIST (embedding_model).
CREATE OR REPLACE FUNCTION nexus.partition_parent_check(p_parent regclass) RETURNS void
LANGUAGE plpgsql
STABLE
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v record;
BEGIN
    SELECT n.nspname, c.relname, c.relkind, pt.partstrat, pt.partnatts,
           (SELECT a.attname FROM pg_catalog.pg_attribute a
             WHERE a.attrelid = c.oid AND a.attnum = pt.partattrs[0]) AS keycol
      INTO v
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
      LEFT JOIN pg_catalog.pg_partitioned_table pt ON pt.partrelid = c.oid
     WHERE c.oid = p_parent;
    IF v.nspname IS DISTINCT FROM 'nexus' OR v.relname !~ '^(chunks|taxonomy_centroids)(_new)?$' THEN
        RAISE EXCEPTION 'nexus partition functions: % is not a parent they serve (nexus.chunks, nexus.taxonomy_centroids and their _new forms)',
            p_parent
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF v.relkind IS DISTINCT FROM 'p' OR v.partstrat IS DISTINCT FROM 'l'
       OR v.partnatts IS DISTINCT FROM 1 OR v.keycol IS DISTINCT FROM 'embedding_model' THEN
        RAISE EXCEPTION 'nexus partition functions: % is not partitioned BY LIST (embedding_model)', p_parent
            USING ERRCODE = 'wrong_object_type';
    END IF;
END
$fn$;

-- Mirror the parent's row-level-security flags, policies and grants onto one child (a model partition or
-- a leaf). Safe to run on a child that already has some: policies and grants the parent does not have are
-- removed, the rest are recreated.
CREATE OR REPLACE FUNCTION nexus.partition_copy_access(p_parent regclass, p_child regclass, p_force boolean)
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_ns    text;
    v_child text;
    r       record;
BEGIN
    SELECT n.nspname::text, c.relname::text INTO v_ns, v_child
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_child;

    EXECUTE pg_catalog.format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', v_ns, v_child);
    IF p_force THEN
        EXECUTE pg_catalog.format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', v_ns, v_child);
    ELSE
        EXECUTE pg_catalog.format('ALTER TABLE %I.%I NO FORCE ROW LEVEL SECURITY', v_ns, v_child);
    END IF;

    -- Policies: drop what the parent does not have, then (re)create each of the parent's.
    FOR r IN
        SELECT p.polname
          FROM pg_catalog.pg_policy p
         WHERE p.polrelid = p_child
           AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_policy q WHERE q.polrelid = p_parent AND q.polname = p.polname)
    LOOP
        EXECUTE pg_catalog.format('DROP POLICY %I ON %I.%I', r.polname, v_ns, v_child);
    END LOOP;
    FOR r IN
        SELECT p.polname, p.polcmd, p.polpermissive,
               (SELECT pg_catalog.string_agg(pg_catalog.quote_ident(ro.rolname), ', ' ORDER BY ro.rolname)
                  FROM pg_catalog.pg_roles ro WHERE ro.oid = ANY (p.polroles)) AS roles,
               pg_catalog.pg_get_expr(p.polqual, p.polrelid) AS qual,
               pg_catalog.pg_get_expr(p.polwithcheck, p.polrelid) AS chk
          FROM pg_catalog.pg_policy p
         WHERE p.polrelid = p_parent
         ORDER BY p.polname
    LOOP
        EXECUTE pg_catalog.format('DROP POLICY IF EXISTS %I ON %I.%I', r.polname, v_ns, v_child);
        EXECUTE pg_catalog.format('CREATE POLICY %I ON %I.%I AS %s FOR %s TO %s%s%s',
            r.polname, v_ns, v_child,
            CASE WHEN r.polpermissive THEN 'PERMISSIVE' ELSE 'RESTRICTIVE' END,
            CASE r.polcmd WHEN 'r' THEN 'SELECT' WHEN 'a' THEN 'INSERT' WHEN 'w' THEN 'UPDATE'
                          WHEN 'd' THEN 'DELETE' ELSE 'ALL' END,
            COALESCE(r.roles, 'PUBLIC'),
            CASE WHEN r.qual IS NULL THEN '' ELSE ' USING (' || r.qual || ')' END,
            CASE WHEN r.chk IS NULL THEN '' ELSE ' WITH CHECK (' || r.chk || ')' END);
    END LOOP;

    -- Grants: revoke what the child has beyond its owner, then grant what the parent has beyond its owner.
    FOR r IN
        SELECT DISTINCT a.grantee
          FROM pg_catalog.pg_class c
         CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a
         WHERE c.oid = p_child AND a.grantee <> c.relowner
    LOOP
        EXECUTE pg_catalog.format('REVOKE ALL ON %I.%I FROM %s', v_ns, v_child,
            CASE WHEN r.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END);
    END LOOP;
    FOR r IN
        SELECT a.grantee, a.privilege_type, a.is_grantable
          FROM pg_catalog.pg_class c
         CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a
         WHERE c.oid = p_parent AND a.grantee <> c.relowner
         ORDER BY a.grantee, a.privilege_type
    LOOP
        EXECUTE pg_catalog.format('GRANT %s ON %I.%I TO %s%s', r.privilege_type, v_ns, v_child,
            CASE WHEN r.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(r.grantee)) END,
            CASE WHEN r.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END);
    END LOOP;
END
$fn$;

-- Create one tenant's leaf under one model partition unless one with that bound exists. True when it created.
CREATE OR REPLACE FUNCTION nexus.partition_ensure_leaf(p_parent regclass, p_model_part regclass, p_tenant text, p_force boolean)
RETURNS boolean
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_ns          text;
    v_parent_name text;
    v_mp_name     text;
    v_model       text;
    v_leaf        text;
    v_taken       record;
BEGIN
    SELECT n.nspname::text, c.relname::text INTO v_ns, v_mp_name
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_model_part;
    SELECT c.relname::text INTO v_parent_name FROM pg_catalog.pg_class c WHERE c.oid = p_parent;
    v_model := nexus.partition_bound_value(p_model_part);
    IF v_model IS NULL THEN
        RAISE EXCEPTION 'nexus.partition_ensure_leaf: % has no single-value LIST bound', p_model_part
            USING ERRCODE = 'wrong_object_type';
    END IF;

    -- The existence check: by bound, never by name.
    PERFORM 1
       FROM pg_catalog.pg_inherits i
      WHERE i.inhparent = p_model_part
        AND nexus.partition_bound_value(i.inhrelid) = p_tenant;
    IF FOUND THEN
        RETURN false;
    END IF;

    v_leaf := nexus.partition_name(v_parent_name, v_model, p_tenant);
    SELECT c.relkind, c.relispartition, pg_catalog.pg_get_expr(c.relpartbound, c.oid) AS bound
      INTO v_taken
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = v_ns AND c.relname = v_leaf;
    IF FOUND THEN
        RAISE EXCEPTION 'nexus partition name collision: %.% already exists and is not the leaf of % under %',
            v_ns, v_leaf, p_tenant, v_mp_name
            USING ERRCODE = 'duplicate_table',
                  DETAIL = pg_catalog.format('relkind %s, partition %s, bound %s',
                                             v_taken.relkind, v_taken.relispartition, COALESCE(v_taken.bound, 'none')),
                  HINT = 'Two tenants hash to one leaf name, or an unrelated relation holds it. The creation is refused.';
    END IF;

    EXECUTE pg_catalog.format('CREATE TABLE %I.%I PARTITION OF %I.%I FOR VALUES IN (%L)',
                              v_ns, v_leaf, v_ns, v_mp_name, p_tenant);
    PERFORM nexus.partition_copy_access(p_parent,
        (pg_catalog.quote_ident(v_ns) || '.' || pg_catalog.quote_ident(v_leaf))::pg_catalog.regclass,
        p_force);
    RETURN true;
END
$fn$;

-- The tenant's leaf under every model partition of the parent. SECURITY DEFINER: nexus_svc calls it (through
-- the service_tokens trigger) and the leaves belong to the schema owner, like every other relation.
CREATE OR REPLACE FUNCTION nexus.create_tenant_partitions(
    p_parent regclass,
    p_tenant text,
    p_force  boolean DEFAULT true
) RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, pg_temp
SET lock_timeout = '2s'
AS $fn$
DECLARE
    v_created integer := 0;
    r         record;
BEGIN
    IF p_tenant IS NULL THEN
        RAISE EXCEPTION 'nexus.create_tenant_partitions: a tenant is required'
            USING ERRCODE = 'null_value_not_allowed';
    END IF;
    PERFORM nexus.partition_parent_check(p_parent);
    -- p_force = false exists for the walk, which fills the *_new parents with FORCE ROW LEVEL SECURITY off.
    -- This function is SECURITY DEFINER and nexus_svc may call it, so on a live parent it would make leaves
    -- without FORCE: refused there.
    IF NOT p_force AND (SELECT c.relname FROM pg_catalog.pg_class c WHERE c.oid = p_parent) !~ '_new$' THEN
        RAISE EXCEPTION 'nexus.create_tenant_partitions: p_force = false is accepted only for a *_new parent, not %', p_parent
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    -- The common case, a second token for a tenant that already has every leaf: ONE catalog query, no lock taken.
    -- A concurrent first creation is invisible here until it commits, so the caller falls through to the advisory
    -- lock below and waits for it (bounded by lock_timeout) instead of racing it.
    IF NOT EXISTS (
        SELECT 1
          FROM pg_catalog.pg_inherits i
         WHERE i.inhparent = p_parent
           AND NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits j
                            WHERE j.inhparent = i.inhrelid
                              AND nexus.partition_bound_value(j.inhrelid) = p_tenant)
    ) THEN
        RETURN 0;
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('nexus.create_tenant_partitions:' || p_tenant, 0));
    FOR r IN
        SELECT i.inhrelid::pg_catalog.regclass AS mp
          FROM pg_catalog.pg_inherits i
          JOIN pg_catalog.pg_class c ON c.oid = i.inhrelid
         WHERE i.inhparent = p_parent
         ORDER BY c.relname
    LOOP
        IF nexus.partition_ensure_leaf(p_parent, r.mp, p_tenant, p_force) THEN
            v_created := v_created + 1;
        END IF;
    END LOOP;
    RETURN v_created;
END
$fn$;

-- The inverse of create_tenant_partitions for ONE tenant: the tenant's rows in the three tables that reference
-- chunks, then its leaf under every model partition of nexus.chunks and nexus.taxonomy_centroids (found by
-- partition bound, never by name), DETACHed and DROPped. Returns the number of leaves dropped; a tenant with no
-- leaves is a no-op, so a repeat returns 0. Refuses 'default'.
--
-- It is NOT SECURITY DEFINER and no engine role may execute it (EXECUTE is revoked from PUBLIC below and granted to
-- nobody): the tenant-removal runbook (RDR-225 Phase 3 Step 2) and the test substrate run it as the schema owner. A
-- definer function here would let any role it was granted to drop another tenant's data.
--
-- The three referencing tables are FORCE ROW LEVEL SECURITY, which binds a non-superuser owner, so the function
-- scopes nexus.tenant to the tenant for its deletes and restores the caller's value before it returns. Without
-- that the deletes would match no row, the drops would still succeed, and the manifest rows of a chunk that no
-- longer exists would be left behind.
--
-- The tenant's service_tokens rows are NOT deleted. The trigger that makes leaves fires on INSERT only, so a
-- token left behind does not bring the leaves back, but a token for a tenant that has no leaves cannot write a
-- chunk: removing the tokens is the runbook's separate, later step (referencing rows, then leaves, then tokens),
-- because revoking access is an authorization decision that belongs in its own visible statement.
CREATE OR REPLACE FUNCTION nexus.drop_tenant_partitions(p_tenant text) RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
SET lock_timeout = '10s'
AS $fn$
DECLARE
    v_dropped integer := 0;
    v_prev    text;
    r         record;
BEGIN
    IF p_tenant IS NULL THEN
        RAISE EXCEPTION 'nexus.drop_tenant_partitions: a tenant is required'
            USING ERRCODE = 'null_value_not_allowed';
    END IF;
    IF p_tenant = 'default' THEN
        RAISE EXCEPTION 'nexus.drop_tenant_partitions: the default tenant is never dropped'
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    -- The same advisory lock create_tenant_partitions takes: a creation and a drop for one tenant serialize.
    PERFORM pg_catalog.pg_advisory_xact_lock(
        pg_catalog.hashtextextended('nexus.create_tenant_partitions:' || p_tenant, 0));

    v_prev := pg_catalog.current_setting('nexus.tenant', true);
    PERFORM pg_catalog.set_config('nexus.tenant', p_tenant, true);
    -- Manifest rows first: their foreign key to the chunks does not cascade, and deleting them stamps
    -- chunk_orphaned_at for the chunks it releases, which is why that table is cleared last.
    DELETE FROM nexus.catalog_document_chunks WHERE tenant_id = p_tenant;
    DELETE FROM nexus.topic_assignments WHERE tenant_id = p_tenant;
    DELETE FROM nexus.chunk_orphaned_at WHERE tenant_id = p_tenant;
    PERFORM pg_catalog.set_config('nexus.tenant', COALESCE(v_prev, ''), true);

    FOR r IN
        SELECT mn.nspname::text AS mp_ns, mp.relname::text AS mp_name,
               ln.nspname::text AS leaf_ns, lc.relname::text AS leaf_name
          FROM pg_catalog.pg_class par
          JOIN pg_catalog.pg_namespace pn ON pn.oid = par.relnamespace AND pn.nspname = 'nexus'
          JOIN pg_catalog.pg_inherits i1 ON i1.inhparent = par.oid
          JOIN pg_catalog.pg_class mp ON mp.oid = i1.inhrelid
          JOIN pg_catalog.pg_namespace mn ON mn.oid = mp.relnamespace
          JOIN pg_catalog.pg_inherits i2 ON i2.inhparent = mp.oid
          JOIN pg_catalog.pg_class lc ON lc.oid = i2.inhrelid
          JOIN pg_catalog.pg_namespace ln ON ln.oid = lc.relnamespace
         WHERE par.relname IN ('chunks', 'taxonomy_centroids')
           AND nexus.partition_bound_value(lc.oid) = p_tenant
         ORDER BY par.relname, mp.relname
    LOOP
        EXECUTE pg_catalog.format('ALTER TABLE %I.%I DETACH PARTITION %I.%I',
                                  r.mp_ns, r.mp_name, r.leaf_ns, r.leaf_name);
        EXECUTE pg_catalog.format('DROP TABLE %I.%I', r.leaf_ns, r.leaf_name);
        v_dropped := v_dropped + 1;
    END LOOP;
    RETURN v_dropped;
END
$fn$;

-- The model partition, its dimension CHECK, and a leaf for every existing tenant. Runs as its caller
-- (a changeset, so the schema owner); not reachable by nexus_svc.
CREATE OR REPLACE FUNCTION nexus.create_model_partition(
    p_parent regclass,
    p_model  text,
    p_force  boolean DEFAULT true
) RETURNS regclass
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_ns          text;
    v_parent_name text;
    v_dim         integer;
    v_dims        integer[];
    v_mp          text;
    v_mp_oid      regclass;
    v_taken       boolean;
    v_tenant      text;
BEGIN
    PERFORM nexus.partition_parent_check(p_parent);
    SELECT n.nspname::text, c.relname::text INTO v_ns, v_parent_name
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE c.oid = p_parent;
    SELECT m.dimension INTO v_dim FROM nexus.embedding_models m WHERE m.embedding_model = p_model;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'nexus.create_model_partition: % is not in nexus.embedding_models', p_model
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    SELECT pg_catalog.array_agg(substring(a.attname FROM '^embedding_([0-9]+)$')::integer ORDER BY substring(a.attname FROM '^embedding_([0-9]+)$')::integer)
      INTO v_dims
      FROM pg_catalog.pg_attribute a
     WHERE a.attrelid = p_parent AND a.attnum > 0 AND NOT a.attisdropped AND a.attname ~ '^embedding_[0-9]+$';
    IF v_dims IS NULL OR NOT (v_dim = ANY (v_dims)) THEN
        RAISE EXCEPTION 'nexus.create_model_partition: % has dimension %, and % has no embedding_% column',
            p_model, v_dim, p_parent, v_dim
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    SELECT i.inhrelid::pg_catalog.regclass INTO v_mp_oid
      FROM pg_catalog.pg_inherits i
     WHERE i.inhparent = p_parent AND nexus.partition_bound_value(i.inhrelid) = p_model;
    IF v_mp_oid IS NULL THEN
        v_mp := nexus.partition_name(v_parent_name, p_model);
        v_taken := EXISTS (SELECT 1 FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
                            WHERE n.nspname = v_ns AND c.relname = v_mp);
        IF v_taken THEN
            RAISE EXCEPTION 'nexus partition name collision: %.% already exists and is not the model partition of % under %',
                v_ns, v_mp, p_model, v_parent_name
                USING ERRCODE = 'duplicate_table';
        END IF;
        EXECUTE pg_catalog.format('CREATE TABLE %I.%I PARTITION OF %I.%I FOR VALUES IN (%L) PARTITION BY LIST (tenant_id)',
                                  v_ns, v_mp, v_ns, v_parent_name, p_model);
        EXECUTE pg_catalog.format('ALTER TABLE %I.%I ADD CONSTRAINT %I CHECK (%s)',
            v_ns, v_mp, v_mp || '_dimension_chk',
            (SELECT pg_catalog.string_agg(pg_catalog.format('%I IS %sNULL', 'embedding_' || d, CASE WHEN d = v_dim THEN 'NOT ' ELSE '' END),
                                          ' AND ' ORDER BY d)
               FROM pg_catalog.unnest(v_dims) AS d));
        v_mp_oid := (pg_catalog.quote_ident(v_ns) || '.' || pg_catalog.quote_ident(v_mp))::pg_catalog.regclass;
        PERFORM nexus.partition_copy_access(p_parent, v_mp_oid, p_force);
    END IF;

    -- The tenants the walk gives leaves to: 'default', every token tenant, and every tenant that already has a
    -- leaf under a sibling model partition of this parent (a tenant with data and no token row got its leaves from
    -- the walk, and a model added later must cover it too).
    FOR v_tenant IN
        SELECT t.tenant_id FROM nexus.service_tokens t
        UNION
        SELECT 'default'
        UNION
        SELECT nexus.partition_bound_value(l.inhrelid)
          FROM pg_catalog.pg_inherits mp
          JOIN pg_catalog.pg_inherits l ON l.inhparent = mp.inhrelid
         WHERE mp.inhparent = p_parent
        ORDER BY 1
    LOOP
        IF v_tenant IS NOT NULL THEN
            PERFORM nexus.partition_ensure_leaf(p_parent, v_mp_oid, v_tenant, p_force);
        END IF;
    END LOOP;
    RETURN v_mp_oid;
END
$fn$;

-- Re-mirror the parent's RLS flags, policies and grants onto every model partition and leaf.
CREATE OR REPLACE FUNCTION nexus.partition_sync_access(p_parent regclass, p_force boolean DEFAULT true)
RETURNS integer
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_n integer := 0;
    r   record;
BEGIN
    PERFORM nexus.partition_parent_check(p_parent);
    FOR r IN
        SELECT t.relid
          FROM pg_catalog.pg_partition_tree(p_parent) t
         WHERE t.level > 0
         ORDER BY t.level, t.relid::pg_catalog.regclass::text
    LOOP
        PERFORM nexus.partition_copy_access(p_parent, r.relid, p_force);
        v_n := v_n + 1;
    END LOOP;
    RETURN v_n;
END
$fn$;

-- The service_tokens AFTER INSERT trigger function. Trigger arguments, when given, name the parents to
-- serve; with none it serves chunks and taxonomy_centroids. DEFINED, NOT ATTACHED: migration step 7.7
-- (bead nexus-3wh8d.8) attaches it, once both parents are partitioned.
CREATE OR REPLACE FUNCTION nexus.service_tokens_create_tenant_partitions() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp
AS $fn$
DECLARE
    v_parent text;
BEGIN
    IF TG_NARGS = 0 THEN
        PERFORM nexus.create_tenant_partitions('nexus.chunks'::pg_catalog.regclass, NEW.tenant_id);
        PERFORM nexus.create_tenant_partitions('nexus.taxonomy_centroids'::pg_catalog.regclass, NEW.tenant_id);
    ELSE
        FOREACH v_parent IN ARRAY TG_ARGV LOOP
            PERFORM nexus.create_tenant_partitions(v_parent::pg_catalog.regclass, NEW.tenant_id);
        END LOOP;
    END IF;
    RETURN NEW;
END
$fn$;

REVOKE EXECUTE ON FUNCTION nexus.partition_name(text, text, text) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.partition_bound_value(regclass) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.partition_parent_check(regclass) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.partition_copy_access(regclass, regclass, boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.partition_ensure_leaf(regclass, regclass, text, boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.create_model_partition(regclass, text, boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.partition_sync_access(regclass, boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.service_tokens_create_tenant_partitions() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.create_tenant_partitions(regclass, text, boolean) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION nexus.drop_tenant_partitions(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION nexus.create_tenant_partitions(regclass, text, boolean) TO nexus_svc;

-- ===========================================================================================
-- THE WALK: RDR-225 migration steps 2 to 7.7. One transaction (the changeset's), so a failure anywhere
-- leaves the old layout untouched. Steps 1 and 8 (freeze and unfreeze) are operational: the engine is not
-- serving while Liquibase runs (stop-start topology).
-- ===========================================================================================

-- A wedged lock fails loudly with a name instead of hanging the boot; a role-level statement_timeout must
-- not kill the copy. Both revert at the end of the transaction.
SET LOCAL lock_timeout = '120s';
SET LOCAL statement_timeout = 0;

DO $w0$
DECLARE
    v_kind "char";
    v_tbl  text;
BEGIN
    IF pg_catalog.to_regclass('nexus.chunks_new') IS NOT NULL
       OR pg_catalog.to_regclass('nexus.taxonomy_centroids_new') IS NOT NULL
       OR pg_catalog.to_regclass('nexus.chunks_retired_225') IS NOT NULL
       OR pg_catalog.to_regclass('nexus.taxonomy_centroids_retired_225') IS NOT NULL THEN
        RAISE EXCEPTION 'vectors-030-1: a chunks_new, taxonomy_centroids_new or *_retired_225 relation already exists in schema nexus: an earlier walk or rollback left it. Restore or drop it by hand before this walk runs (the retired tables are the 14-day recovery copy; do not drop them unread).'
            USING ERRCODE = 'duplicate_table';
    END IF;
    FOREACH v_tbl IN ARRAY ARRAY['chunks', 'taxonomy_centroids'] LOOP
        SELECT c.relkind INTO v_kind FROM pg_catalog.pg_class c
         WHERE c.oid = pg_catalog.to_regclass('nexus.' || v_tbl);
        IF v_kind IS DISTINCT FROM 'r' THEN
            RAISE EXCEPTION 'vectors-030-1: nexus.% is not an ordinary table (relkind %), so it is already partitioned or missing; nothing for this walk to migrate', v_tbl, v_kind
                USING ERRCODE = 'wrong_object_type';
        END IF;
    END LOOP;
END
$w0$;

-- Steps 2 to 6 read and write these tables as a role with no BYPASSRLS, so FORCE is off on every one of them
-- until step 7.7 puts it back (hygiene-002, vectors-004 precedent). NO FORCE only removes row-level security
-- for the table OWNER; nexus_svc is not the owner and is subject to the policies throughout.
ALTER TABLE nexus.chunks NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.taxonomy_centroids NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_collections NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.catalog_document_chunks NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.topic_assignments NO FORCE ROW LEVEL SECURITY;
ALTER TABLE nexus.chunk_orphaned_at NO FORCE ROW LEVEL SECURITY;

-- ===========================================================================================
-- STEP 2: the partitioned replacements, their model partitions and their tenant leaves.
-- Same column set as the live tables plus embedding_model (last), the new primary key and the constraints
-- that can be enforced during the copy, and NO secondary indexes yet (step 5 builds them after the copy).
-- ===========================================================================================
CREATE TABLE nexus.chunks_new (
    LIKE nexus.chunks INCLUDING DEFAULTS INCLUDING GENERATED INCLUDING COMMENTS,
    embedding_model text NOT NULL
) PARTITION BY LIST (embedding_model);
ALTER TABLE nexus.chunks_new
    ADD CONSTRAINT chunks_new_pk PRIMARY KEY (tenant_id, collection, chash, embedding_model);
ALTER TABLE nexus.chunks_new
    ADD CONSTRAINT chunks_content_retention_consistent CHECK ((chunk_text IS NULL) = (retention = 'reference-only'));
ALTER TABLE nexus.chunks_new
    ADD CONSTRAINT chunks_retention_chk CHECK (retention IN ('reference-only', 'full'));
ALTER TABLE nexus.chunks_new
    ADD CONSTRAINT exactly_one_embedding CHECK (num_nonnulls(embedding_384, embedding_768, embedding_1024) = 1);

CREATE TABLE nexus.taxonomy_centroids_new (
    LIKE nexus.taxonomy_centroids INCLUDING DEFAULTS INCLUDING GENERATED INCLUDING COMMENTS,
    embedding_model text NOT NULL
) PARTITION BY LIST (embedding_model);
ALTER TABLE nexus.taxonomy_centroids_new
    ADD CONSTRAINT taxonomy_centroids_new_pk PRIMARY KEY (tenant_id, collection, topic_id, embedding_model);
ALTER TABLE nexus.taxonomy_centroids_new
    ADD CONSTRAINT taxonomy_centroids_exactly_one_embedding CHECK (num_nonnulls(embedding_384, embedding_768, embedding_1024) = 1);

-- Row-level security, policies and grants of the live tables onto the new parents (FORCE stays off until 7.7).
-- The leaves copy the parent's access as they are created, so this precedes them.
SELECT nexus.partition_copy_access('nexus.chunks'::regclass, 'nexus.chunks_new'::regclass, false);
SELECT nexus.partition_copy_access('nexus.taxonomy_centroids'::regclass, 'nexus.taxonomy_centroids_new'::regclass, false);

DO $w2$
DECLARE
    r        record;
    v_tenant text;
BEGIN
    -- A partition per model the engine knows (the four seeded models), each with a leaf for every token tenant
    -- and for 'default'.
    FOR r IN SELECT m.embedding_model, m.dimension FROM nexus.embedding_models m ORDER BY m.embedding_model LOOP
        IF r.dimension NOT IN (384, 768, 1024) THEN
            RAISE WARNING 'rdr225 step 2: embedding model % has dimension %, which has no typed vector column; it gets no partition',
                r.embedding_model, r.dimension;
            CONTINUE;
        END IF;
        PERFORM nexus.create_model_partition('nexus.chunks_new'::regclass, r.embedding_model, false);
        PERFORM nexus.create_model_partition('nexus.taxonomy_centroids_new'::regclass, r.embedding_model, false);
    END LOOP;
    -- Every other tenant that holds data: any tenant_id present in chunks or taxonomy_centroids. Both parents
    -- get the leaves, so every tenant seen anywhere has the same leaf set and the copy always finds a
    -- partition. ('default' and the token tenants already have theirs from create_model_partition.)
    FOR v_tenant IN
        SELECT t.tenant_id FROM (SELECT c.tenant_id FROM nexus.chunks c GROUP BY c.tenant_id
                                 UNION
                                 SELECT ct.tenant_id FROM nexus.taxonomy_centroids ct GROUP BY ct.tenant_id) t
         ORDER BY t.tenant_id
    LOOP
        PERFORM nexus.create_tenant_partitions('nexus.chunks_new'::regclass, v_tenant, false);
        PERFORM nexus.create_tenant_partitions('nexus.taxonomy_centroids_new'::regclass, v_tenant, false);
    END LOOP;
END
$w2$;

-- ===========================================================================================
-- STEP 3: copy, one collection at a time (a collection has exactly one model, so this is a copy per
-- (model, tenant) and each statement is an index range scan of the old primary key). Rows hidden by
-- RDR-192's liveness rule are copied unchanged. A row whose vector column disagrees with its model fails the
-- model partition's dimension CHECK and rolls the walk back. Centroids: only those whose collection has a
-- registry row are copied (derived data: taxonomy rebuilds the rest, and they stay in
-- taxonomy_centroids_retired_225).
-- ===========================================================================================
DO $w3$
DECLARE
    r       record;
    v_n     bigint;
    v_total bigint := 0;
BEGIN
    FOR r IN
        SELECT cc.tenant_id, cc.name AS collection, cc.embedding_model AS model
          FROM nexus.catalog_collections cc
         WHERE EXISTS (SELECT 1 FROM nexus.chunks c WHERE c.tenant_id = cc.tenant_id AND c.collection = cc.name)
         ORDER BY cc.embedding_model, cc.tenant_id, cc.name
    LOOP
        INSERT INTO nexus.chunks_new
            (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024,
             metadata, created_at, retention, last_written_at, embedding_model)
        SELECT c.tenant_id, c.collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024,
               c.metadata, c.created_at, c.retention, c.last_written_at, r.model
          FROM nexus.chunks c
         WHERE c.tenant_id = r.tenant_id AND c.collection = r.collection;
        GET DIAGNOSTICS v_n = ROW_COUNT;
        v_total := v_total + v_n;
    END LOOP;
    RAISE LOG 'rdr225 step 3: % chunk row(s) copied', v_total;

    INSERT INTO nexus.taxonomy_centroids_new
        (tenant_id, collection, topic_id, embedding_384, embedding_768, embedding_1024, label, doc_count,
         created_at, embedding_model)
    SELECT ct.tenant_id, ct.collection, ct.topic_id, ct.embedding_384, ct.embedding_768, ct.embedding_1024,
           ct.label, ct.doc_count, ct.created_at, cc.embedding_model
      FROM nexus.taxonomy_centroids ct
      JOIN nexus.catalog_collections cc ON cc.tenant_id = ct.tenant_id AND cc.name = ct.collection;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    RAISE LOG 'rdr225 step 3: % centroid row(s) copied', v_n;
END
$w3$;

-- The three constraints that could not be enforced during the copy come after it. The old one is NOT VALID
-- (legacy rows may not hold it); the new one keeps that state and checks every later write.
ALTER TABLE nexus.chunks_new
    ADD CONSTRAINT chunks_chash_octet_check CHECK (octet_length(chash) = 32) NOT VALID;

-- ===========================================================================================
-- STEP 4: embedding_model on the three referencing tables: nullable, backfilled from the collection's
-- registry row, then NOT NULL (the foreign keys are MATCH SIMPLE, so a NULL would exempt a row). The
-- manifest's stamp trigger is off for the backfill: it never changes (tenant, collection, chash), so the
-- trigger's work is empty, and a statement trigger over millions of transition rows is not free.
-- ===========================================================================================
ALTER TABLE nexus.catalog_document_chunks DISABLE TRIGGER trg_catalog_chunks_stamp_on_update;
ALTER TABLE nexus.catalog_document_chunks ADD COLUMN IF NOT EXISTS embedding_model text;
UPDATE nexus.catalog_document_chunks m
   SET embedding_model = cc.embedding_model
  FROM nexus.catalog_collections cc
 WHERE cc.tenant_id = m.tenant_id AND cc.name = m.collection;
ALTER TABLE nexus.catalog_document_chunks ALTER COLUMN embedding_model SET NOT NULL;
ALTER TABLE nexus.catalog_document_chunks ENABLE TRIGGER trg_catalog_chunks_stamp_on_update;

ALTER TABLE nexus.topic_assignments ADD COLUMN IF NOT EXISTS embedding_model text;
UPDATE nexus.topic_assignments ta
   SET embedding_model = cc.embedding_model
  FROM nexus.catalog_collections cc
 WHERE cc.tenant_id = ta.tenant_id AND cc.name = ta.source_collection;
ALTER TABLE nexus.topic_assignments ALTER COLUMN embedding_model SET NOT NULL;

ALTER TABLE nexus.chunk_orphaned_at ADD COLUMN IF NOT EXISTS embedding_model text;
UPDATE nexus.chunk_orphaned_at q
   SET embedding_model = cc.embedding_model
  FROM nexus.catalog_collections cc
 WHERE cc.tenant_id = q.tenant_id AND cc.name = q.collection;
ALTER TABLE nexus.chunk_orphaned_at ALTER COLUMN embedding_model SET NOT NULL;

-- ===========================================================================================
-- STEP 5: the secondary indexes (the live tables' own definitions, replayed on the parents under a _new
-- name that step 7.5 renames), then statistics. Autovacuum never analyzes a partitioned parent, and a
-- bulk-copied table without statistics turns the planner off HNSW (vectors-004 Step 5b, BUG-0148), so every
-- leaf, the parents and the rewritten referencing tables are analyzed here.
-- ===========================================================================================
DO $w5$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT i.tablename, i.indexname, i.indexdef
          FROM pg_catalog.pg_indexes i
         WHERE i.schemaname = 'nexus'
           AND i.tablename IN ('chunks', 'taxonomy_centroids')
           AND i.indexdef NOT LIKE 'CREATE UNIQUE%'
         ORDER BY i.tablename, i.indexname
    LOOP
        EXECUTE pg_catalog.replace(pg_catalog.replace(r.indexdef,
                    ' ON nexus.' || r.tablename || ' ', ' ON nexus.' || r.tablename || '_new '),
                    'INDEX ' || r.indexname || ' ', 'INDEX ' || r.indexname || '_new ');
    END LOOP;

    FOR r IN
        SELECT t.relid::pg_catalog.regclass AS rel
          FROM pg_catalog.pg_partition_tree('nexus.chunks_new'::pg_catalog.regclass) t
         WHERE t.isleaf
        UNION ALL
        SELECT t.relid::pg_catalog.regclass
          FROM pg_catalog.pg_partition_tree('nexus.taxonomy_centroids_new'::pg_catalog.regclass) t
         WHERE t.isleaf
    LOOP
        EXECUTE pg_catalog.format('ANALYZE %s', r.rel);
    END LOOP;
END
$w5$;
ANALYZE nexus.chunks_new;
ANALYZE nexus.taxonomy_centroids_new;
ANALYZE nexus.catalog_document_chunks;
ANALYZE nexus.topic_assignments;
ANALYZE nexus.chunk_orphaned_at;

-- ===========================================================================================
-- STEP 6: reconcile exactly, per (model, tenant), for both tables. A mismatch fails the changeset and rolls
-- the whole walk back.
-- ===========================================================================================
DO $w6$
DECLARE
    v_bad     text;
    v_old     bigint;
    v_new     bigint;
    v_skipped bigint;
BEGIN
    SELECT string_agg(pg_catalog.format('(model %s, tenant %s: old %s, new %s)', x.model, x.tenant_id, x.old_n, x.new_n), '; ')
      INTO v_bad
      FROM (SELECT COALESCE(o.model, n.model) AS model, COALESCE(o.tenant_id, n.tenant_id) AS tenant_id,
                   COALESCE(o.n, 0) AS old_n, COALESCE(n.n, 0) AS new_n
              FROM (SELECT cc.embedding_model AS model, c.tenant_id, count(*) AS n
                      FROM nexus.chunks c
                      JOIN nexus.catalog_collections cc ON cc.tenant_id = c.tenant_id AND cc.name = c.collection
                     GROUP BY 1, 2) o
              FULL JOIN (SELECT k.embedding_model AS model, k.tenant_id, count(*) AS n
                           FROM nexus.chunks_new k GROUP BY 1, 2) n
                ON n.model = o.model AND n.tenant_id = o.tenant_id
             WHERE COALESCE(o.n, 0) <> COALESCE(n.n, 0)
             ORDER BY 1, 2
             LIMIT 20) x;
    IF v_bad IS NOT NULL THEN
        RAISE EXCEPTION 'vectors-030-1 step 6: chunk copy does not reconcile per (model, tenant): %', v_bad;
    END IF;
    SELECT count(*) INTO v_old FROM nexus.chunks;
    SELECT count(*) INTO v_new FROM nexus.chunks_new;
    IF v_old <> v_new THEN
        RAISE EXCEPTION 'vectors-030-1 step 6: % chunk row(s) in the old table, % in the new (a chunk with no registered collection?)', v_old, v_new;
    END IF;

    SELECT string_agg(pg_catalog.format('(model %s, tenant %s: old %s, new %s)', x.model, x.tenant_id, x.old_n, x.new_n), '; ')
      INTO v_bad
      FROM (SELECT COALESCE(o.model, n.model) AS model, COALESCE(o.tenant_id, n.tenant_id) AS tenant_id,
                   COALESCE(o.n, 0) AS old_n, COALESCE(n.n, 0) AS new_n
              FROM (SELECT cc.embedding_model AS model, ct.tenant_id, count(*) AS n
                      FROM nexus.taxonomy_centroids ct
                      JOIN nexus.catalog_collections cc ON cc.tenant_id = ct.tenant_id AND cc.name = ct.collection
                     GROUP BY 1, 2) o
              FULL JOIN (SELECT k.embedding_model AS model, k.tenant_id, count(*) AS n
                           FROM nexus.taxonomy_centroids_new k GROUP BY 1, 2) n
                ON n.model = o.model AND n.tenant_id = o.tenant_id
             WHERE COALESCE(o.n, 0) <> COALESCE(n.n, 0)
             ORDER BY 1, 2
             LIMIT 20) x;
    IF v_bad IS NOT NULL THEN
        RAISE EXCEPTION 'vectors-030-1 step 6: centroid copy does not reconcile per (model, tenant): %', v_bad;
    END IF;
    SELECT count(*) INTO v_old FROM nexus.taxonomy_centroids;
    SELECT count(*) INTO v_new FROM nexus.taxonomy_centroids_new;
    -- The centroids with no registry row are derived data and are not copied; the rest must all be there.
    SELECT count(*) INTO v_skipped
      FROM nexus.taxonomy_centroids ct
     WHERE NOT EXISTS (SELECT 1 FROM nexus.catalog_collections cc
                        WHERE cc.tenant_id = ct.tenant_id AND cc.name = ct.collection);
    IF v_old <> v_new + v_skipped THEN
        RAISE EXCEPTION 'vectors-030-1 step 6: % centroid row(s) in the old table, % copied and % with no registered collection', v_old, v_new, v_skipped;
    END IF;
    RAISE LOG 'rdr225 step 6: reconciled';
END
$w6$;

-- ===========================================================================================
-- STEP 7: the swap.
-- 7.1  The three inbound foreign keys and the three views over the old tables go. The views bind by OID, so
--      they would otherwise follow the retired table. Definitions, options and grants are kept to recreate
--      them at 7.7. The schema owner may drop a view another role owns, so a superuser-owned
--      diag_chash_conformance (pg_provision creates it that way) is dropped and recreated owned by the migrating
--      role, which is the shape taxonomy-011-8 gives it. A migrating role that is neither the view's owner nor the
--      schema's owner cannot drop it: a WARNING names the view, the walk carries on, and the view's owner must run
--      DROP VIEW (taxonomy-011-8 then recreates it over the new table). That branch is not exercised by a test.
-- ===========================================================================================
ALTER TABLE nexus.catalog_document_chunks DROP CONSTRAINT fk_catalog_chunks_chunk;
ALTER TABLE nexus.topic_assignments DROP CONSTRAINT topic_assignments_chunk_fk;
ALTER TABLE nexus.chunk_orphaned_at DROP CONSTRAINT chunk_orphaned_at_chunk_fk;

CREATE TEMP TABLE _p225_views ON COMMIT DROP AS
SELECT c.relname::text AS view_name,
       pg_catalog.regexp_replace(pg_catalog.pg_get_viewdef(c.oid, true), ';\s*$', '') AS def,
       c.reloptions AS reloptions,
       c.relacl AS relacl,
       c.relowner AS old_owner
  FROM pg_catalog.pg_class c
  JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
 WHERE n.nspname = 'nexus' AND c.relkind = 'v'
   AND c.relname IN ('live_chunks', 'collection_vector_stats', 'diag_chash_conformance');

DO $w71$
DECLARE
    r record;
BEGIN
    FOR r IN SELECT v.view_name FROM _p225_views v ORDER BY v.view_name LOOP
        BEGIN
            EXECUTE pg_catalog.format('DROP VIEW nexus.%I', r.view_name);
        EXCEPTION WHEN insufficient_privilege THEN
            RAISE WARNING 'rdr225 step 7.1: nexus.% is owned by another role, so it was not dropped and stays bound to the retired table. Its owner must run DROP VIEW nexus.% (taxonomy-011-8 or the owner then recreates it over the new table)',
                r.view_name, r.view_name;
        END;
    END LOOP;
END
$w71$;

-- 7.2  The old tables' indexes and index-backed constraints get a _retired_225 suffix (those names are
--      schema-wide); CHECK and FK constraint names are per table and need none.
DO $w72$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT tc.relname AS tbl, ic.relname AS idx, k.conname AS con
          FROM pg_catalog.pg_index i
          JOIN pg_catalog.pg_class ic ON ic.oid = i.indexrelid
          JOIN pg_catalog.pg_class tc ON tc.oid = i.indrelid
          LEFT JOIN pg_catalog.pg_constraint k ON k.conindid = i.indexrelid AND k.conrelid = i.indrelid
         WHERE i.indrelid IN ('nexus.chunks'::pg_catalog.regclass, 'nexus.taxonomy_centroids'::pg_catalog.regclass)
         ORDER BY tc.relname, ic.relname
    LOOP
        IF r.con IS NOT NULL THEN
            EXECUTE pg_catalog.format('ALTER TABLE nexus.%I RENAME CONSTRAINT %I TO %I', r.tbl, r.con, r.con || '_retired_225');
        ELSE
            EXECUTE pg_catalog.format('ALTER INDEX nexus.%I RENAME TO %I', r.idx, r.idx || '_retired_225');
        END IF;
    END LOOP;
END
$w72$;

-- 7.3  The old outbound foreign key goes, so it cannot block registry deletes.
ALTER TABLE nexus.chunks DROP CONSTRAINT chunks_collection_fk;

-- 7.4  The swap itself.
ALTER TABLE nexus.chunks RENAME TO chunks_retired_225;
ALTER TABLE nexus.chunks_new RENAME TO chunks;
ALTER TABLE nexus.taxonomy_centroids RENAME TO taxonomy_centroids_retired_225;
ALTER TABLE nexus.taxonomy_centroids_new RENAME TO taxonomy_centroids;

-- 7.5  The new parents' indexes and primary keys take the old names.
DO $w75$
DECLARE
    r record;
BEGIN
    FOR r IN
        SELECT tc.relname AS tbl, ic.relname AS idx, k.conname AS con
          FROM pg_catalog.pg_index i
          JOIN pg_catalog.pg_class ic ON ic.oid = i.indexrelid
          JOIN pg_catalog.pg_class tc ON tc.oid = i.indrelid
          LEFT JOIN pg_catalog.pg_constraint k ON k.conindid = i.indexrelid AND k.conrelid = i.indrelid
         WHERE i.indrelid IN ('nexus.chunks'::pg_catalog.regclass, 'nexus.taxonomy_centroids'::pg_catalog.regclass)
           AND (ic.relname LIKE '%\_new' OR ic.relname LIKE '%\_new\_pk')
         ORDER BY tc.relname, ic.relname
    LOOP
        IF r.con IS NOT NULL THEN
            EXECUTE pg_catalog.format('ALTER TABLE nexus.%I RENAME CONSTRAINT %I TO %I', r.tbl, r.con,
                                      pg_catalog.regexp_replace(r.con, '_new_pk$', '_pk'));
        ELSE
            EXECUTE pg_catalog.format('ALTER INDEX nexus.%I RENAME TO %I', r.idx,
                                      pg_catalog.regexp_replace(r.idx, '_new$', ''));
        END IF;
    END LOOP;
END
$w75$;

-- 7.6  The four-column inbound foreign keys, with their old names, actions and deferrability: NOT VALID, then
--      VALIDATE (their referencing tables are not partitioned). The outbound composite model foreign key is
--      validated directly, because PostgreSQL does not take NOT VALID for a partitioned referencing table.
ALTER TABLE nexus.catalog_document_chunks
    ADD CONSTRAINT fk_catalog_chunks_chunk
    FOREIGN KEY (tenant_id, collection, chash, embedding_model)
    REFERENCES nexus.chunks (tenant_id, collection, chash, embedding_model)
    ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE NOT VALID;
-- Guarded shape (nexus-4m6i0): the constraint was added three lines up in this transaction, so the guard
-- is always true; it is what the VALIDATE CONSTRAINT precondition lint accepts.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_catalog_chunks_chunk') THEN
        ALTER TABLE nexus.catalog_document_chunks VALIDATE CONSTRAINT fk_catalog_chunks_chunk;
    END IF;
END
$$;

ALTER TABLE nexus.topic_assignments
    ADD CONSTRAINT topic_assignments_chunk_fk
    FOREIGN KEY (tenant_id, source_collection, doc_id, embedding_model)
    REFERENCES nexus.chunks (tenant_id, collection, chash, embedding_model)
    ON UPDATE CASCADE ON DELETE CASCADE NOT VALID;
-- Guarded shape (nexus-4m6i0): the constraint was added three lines up in this transaction, so the guard
-- is always true; it is what the VALIDATE CONSTRAINT precondition lint accepts.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'topic_assignments_chunk_fk') THEN
        ALTER TABLE nexus.topic_assignments VALIDATE CONSTRAINT topic_assignments_chunk_fk;
    END IF;
END
$$;

ALTER TABLE nexus.chunk_orphaned_at
    ADD CONSTRAINT chunk_orphaned_at_chunk_fk
    FOREIGN KEY (tenant_id, collection, chash, embedding_model)
    REFERENCES nexus.chunks (tenant_id, collection, chash, embedding_model)
    ON UPDATE CASCADE ON DELETE CASCADE NOT VALID;
-- Guarded shape (nexus-4m6i0): the constraint was added three lines up in this transaction, so the guard
-- is always true; it is what the VALIDATE CONSTRAINT precondition lint accepts.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'chunk_orphaned_at_chunk_fk') THEN
        ALTER TABLE nexus.chunk_orphaned_at VALIDATE CONSTRAINT chunk_orphaned_at_chunk_fk;
    END IF;
END
$$;

ALTER TABLE nexus.chunks
    ADD CONSTRAINT chunks_collection_fk
    FOREIGN KEY (tenant_id, collection, embedding_model)
    REFERENCES nexus.catalog_collections (tenant_id, name, embedding_model)
    ON DELETE RESTRICT;

-- 7.7  The views over the new tables (definition, options and grants as they were); the parents' policies and
--      grants were copied at step 2, and every leaf and model partition is re-mirrored from them here with FORCE;
--      FORCE comes back on every table the walk toggled (the retired tables keep it, so they hold no row a
--      tenant can read without its GUC); and the service_tokens trigger is attached, which is the only place
--      it is created.
DO $w77$
DECLARE
    r record;
    a record;
BEGIN
    FOR r IN SELECT v.view_name, v.def, v.reloptions, v.relacl, v.old_owner FROM _p225_views v
                  WHERE pg_catalog.to_regclass('nexus.' || pg_catalog.quote_ident(v.view_name)) IS NULL
                  ORDER BY v.view_name LOOP
        EXECUTE pg_catalog.format('CREATE VIEW nexus.%I%s AS %s', r.view_name,
                                  CASE WHEN r.reloptions IS NULL THEN ''
                                       ELSE ' WITH (' || pg_catalog.array_to_string(r.reloptions, ', ') || ')' END,
                                  r.def);
        IF r.relacl IS NOT NULL THEN
            FOR a IN
                SELECT x.grantee, x.privilege_type, x.is_grantable
                  FROM pg_catalog.aclexplode(r.relacl) x
                 WHERE x.grantee <> (SELECT c.relowner FROM pg_catalog.pg_class c WHERE c.oid = ('nexus.' || pg_catalog.quote_ident(r.view_name))::pg_catalog.regclass)
                   AND x.grantee <> r.old_owner
                 ORDER BY x.grantee, x.privilege_type
            LOOP
                EXECUTE pg_catalog.format('GRANT %s ON nexus.%I TO %s%s', a.privilege_type, r.view_name,
                    CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END,
                    CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END);
            END LOOP;
        END IF;
    END LOOP;
END
$w77$;

