-- =========================================================================================== -- STEP 7.8: redefine, once and only here, every write site and the manifest triggers against the swapped -- tables. Each body is the LATEST live body (the master changelog read in include order) with only the -- RDR-225 edits marked in its comments: the chunk-inserting functions supply embedding_model and use the -- four-column primary key as the arbiter, the manifest-referencing writers supply embedding_model, the -- stamp triggers carry the chunk's model and join on four columns (chunk_orphaned_at keeps its own -- three-column arbiter), and purge_trash qualifies the constraint name it defers. vectors-026, -027 and -- -028 and every read function were checked and need no change: their joins are on (tenant, collection, -- chash), and a collection has exactly one model, so they stay correct without the extra column. -- =========================================================================================== -- ---- gc_quarantine_orphans CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans(dim integer, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit integer) RETURNS TABLE(moved bigint, sample jsonb) LANGUAGE plpgsql AS $function$ DECLARE v_moved bigint; v_sample jsonb; v_collision_count bigint; v_collision_sample text[]; v_sample_limit int; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- nexus-0uuit/sybbh crit-fix critique 2026-08-19 (code-review-expert): -- p_sample_limit is caller-supplied over HTTP (VectorHandler's -- handleGcQuarantineOrphans, optInt default 20) and unlike purge_trash / -- gc_expire_quarantine (both hard-capped in-function), this function -- previously trusted it unbounded -- a caller passing a large -- sample_limit could insert a gc_audit row with an unbounded chashes -- array. VectorHandler now clamps server-side too, but this is defense -- in depth: the SAME GC_AUDIT_MAX_CHASHES cap (5000, CatalogRepository. -- java) enforced here independently of the HTTP layer. Carried forward -- from catalog-033-2 into this changeset's body (nexus-uxd2a; see this -- changeset's own comment above). v_sample_limit := LEAST(GREATEST(COALESCE(p_sample_limit, 20), 0), 5000);
-- nexus-sa731: EXCLUSIVE half of the RDR-191 sweep gate (unchanged from -- catalog-028-1 — see that changeset's comment for the full derivation). PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '5000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'gc_quarantine_orphans: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer is holding it; retry', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- RDR-192 Step 8 (nexus-wbfpw.16): the candidate set is reapable(c), nexus.chunk_is_reapable -- (vectors-021): no own-collection manifest row in any owner state, last_written_at past the -- grace (default 30 days), not a quarantine sibling. It is chosen ONCE here and every later -- statement reads this one set, so a condition that lapses between the copy INSERT and the -- DELETE cannot delete a chunk that was not copied. The DELETE re-checks the predicate on its -- target row, so a client write that refreshes last_written_at after this point wins at the -- READ COMMITTED recheck and the chunk stays. CREATE TEMP TABLE IF NOT EXISTS _wbfpw16_victim(chash bytea PRIMARY KEY) ON COMMIT DROP; DELETE FROM _wbfpw16_victim; INSERT INTO _wbfpw16_victim(chash) SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL));
IF NOT EXISTS (SELECT 1 FROM _wbfpw16_victim) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb; RETURN; END IF;
-- N7-STYLE cross-dim collision guard (Critical-1 fix, T2 [22454]): the -- unified PK (tenant_id, collection, chash) cannot hold two different- -- dim rows. Detect, BEFORE any row moves, any orphan whose chash -- already exists at p_quarantine_collection under a DIFFERENT -- populated embedding_<dim> column than the orphan's own -- the blind -- ON CONFLICT ... DO UPDATE ... EXCLUDED below would otherwise -- silently overwrite (destroy) one of the two chunks' text/embedding. -- RAISE aborts only THIS (tenant, collection) sweep call -- an ongoing -- GC cycle, not vectors-004's one-time migration, so the bounded -- blast radius is one collection's pass, retried next cycle, not the -- whole batch. WITH orphan AS ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim FROM nexus.chunks c JOIN _wbfpw16_victim v ON v.chash = c.chash WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection ), collision AS ( SELECT o.chash, o.src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM orphan o JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND e.collection = p_quarantine_collection AND e.chash = o.chash ) SELECT count(*), COALESCE(array_agg(encode(chash, 'hex') ORDER BY chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM collision WHERE src_dim IS DISTINCT FROM existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=% -- the unified PK cannot hold two different-dim rows for the same chash (mirrors vectors-004''s N7 guard, T2 22454). Sample chashes: %. Refusing to overwrite; verify the quarantine-collection naming keeps distinct dims/collections separated before retrying.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- Registration MUST precede the copy INSERT below (FK on collection). -- RDR-204 nexus-uxd2a (hygiene-005-1): NO ENGINE PATH DERIVES A -- COLLECTION'S ATTRIBUTES FROM ITS NAME (coordinator nexus-71 -- decision -- see this changelog file's own header). The PRIOR body -- (hygiene-002-2) parsed p_quarantine_collection's OWN name via -- string_to_array(name, '__') -- for the real production shape -- "quarantine-<ct>__owner__model__vN" that split v_seg[1] to the -- LITERAL FIRST SEGMENT, "quarantine-<ct>" WITH THE PREFIX STILL -- ATTACHED (the migration-time walk's regex-based branch B, by -- contrast, has always captured the base type via a capture group that -- excludes the prefix) -- shipped as a live defect (nexus-uxd2a: a real -- row landed with content_type = 'quarantine-code', outside the CCE -- profile vocabulary). p_collection (the ORIGIN) is ALWAYS already -- registered by this point -- every caller resolves dim from it before -- ever reaching this function (PgVectorRepository.quarantineOrphans) -- -- so its own row is the one true source for the quarantine sibling's -- attributes. An unregistered origin is now a fail-loud precondition, -- never a silent 'unknown' stub. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from the quarantine sibling name (RDR-204 nexus-uxd2a); register the origin before quarantining orphans', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension;
-- RDR-225: the row carries its own embedding_model (the quarantine sibling is registered under the -- origin's model just above, so the model is the same and the composite collection foreign key holds), -- and the arbiter is the four-column primary key of the partitioned table. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, embedding_model) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection), c.embedding_model FROM nexus.chunks c JOIN _wbfpw16_victim v ON v.chash = c.chash WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection ON CONFLICT (tenant_id, collection, chash, embedding_model) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata;
WITH del AS ( DELETE FROM nexus.chunks c USING _wbfpw16_victim v WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = v.chash AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL)) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT v_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
-- nexus-sybbh: audit the move IN THE SAME TRANSACTION as the DELETE -- above. `chashes` here is deliberately the v_sample_limit-capped -- sample the function already computes (extracting just the chash -- field) -- chash_count still carries the exact full v_moved count -- regardless of sample size. `chashes_truncated`/`chashes_stored` are -- set (same convention as purge_trash / gc_expire_quarantine) only -- when the CALLER's requested p_sample_limit itself exceeded -- GC_AUDIT_MAX_CHASHES and had to be clamped -- distinct from -- `chashes_is_sample`, which is always true here by design (the sample -- is intentionally partial even when p_sample_limit is well within -- bounds). Carried forward from catalog-033-2 into this changeset's -- body (nexus-uxd2a; catalog-033-2's original comment, adapted). INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_quarantine_orphans', p_collection, 'engine', false, v_moved, COALESCE( (SELECT jsonb_agg(elem->>'chash') FROM jsonb_array_elements(COALESCE(v_sample, '[]'::jsonb)) elem), '[]'::jsonb), jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'sample_limit', v_sample_limit, 'chashes_is_sample', true) || CASE WHEN COALESCE(p_sample_limit, 20) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END );
RETURN QUERY SELECT v_moved, v_sample; END; $function$;
-- ---- gc_quarantine_orphans_bounded CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans_bounded(dim integer, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit integer, p_row_limit integer) RETURNS TABLE(moved bigint, sample jsonb, remaining bigint) LANGUAGE plpgsql AS $function$ DECLARE v_moved bigint; v_sample jsonb; v_remaining bigint; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; v_collision_count bigint; v_collision_sample text[]; v_sample_limit int; v_row_limit int; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- A non-positive bound is a caller error, not "unbounded". The whole point -- of this function is the bound; silently removing it would hand back the -- 58-second transaction this exists to prevent. IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: p_row_limit must be positive, got %. Use nexus.gc_quarantine_orphans for the unbounded sweep.', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
v_sample_limit := LEAST(GREATEST(COALESCE(p_sample_limit, 20), 0), 5000); v_row_limit := LEAST(p_row_limit, 100000);
PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '25000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN -- nexus-a6mon requirement 4: name the caller's OWN in-flight call as -- a possibility. The unbounded form advised "retry", which cannot -- succeed while the holder IS the caller's previous, still-committing -- call -- the exact state a cut-then-resubmit loop produces. RAISE EXCEPTION 'gc_quarantine_orphans_bounded: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer holds it, OR your own previous bounded call is still committing after the edge cut you. Poll pg_stat_activity for an active sweep on this collection before retrying; a fixed sleep builds a lock convoy.', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- THE VICTIM SET, chosen ONCE and ordered for deterministic progress. -- RDR-192 Step 8 (nexus-wbfpw.16): a candidate is reapable(c), nexus.chunk_is_reapable -- (vectors-021): no own-collection manifest row in any owner state, last_written_at past -- the grace (default 30 days), not a quarantine sibling. The DELETE below re-checks it on -- the target row, so a refresh that lands after the victim set was chosen wins at the -- READ COMMITTED recheck and the chunk stays. CREATE TEMP TABLE IF NOT EXISTS _a6mon_victim(chash bytea PRIMARY KEY) ON COMMIT DROP; DELETE FROM _a6mon_victim; INSERT INTO _a6mon_victim(chash) SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL)) ORDER BY c.chash LIMIT v_row_limit;
IF NOT EXISTS (SELECT 1 FROM _a6mon_victim) THEN RETURN QUERY SELECT 0::bigint, NULL::jsonb, 0::bigint; RETURN; END IF;
-- Cross-dim collision guard, same contract as the unbounded form -- (vectors-004's N7 guard, T2 22454) but scoped to this batch. SELECT count(*), COALESCE(array_agg(encode(x.chash, 'hex') ORDER BY x.chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM nexus.chunks c JOIN _a6mon_victim v ON v.chash = c.chash JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND e.collection = p_quarantine_collection AND e.chash = c.chash WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection ) x WHERE x.src_dim IS DISTINCT FROM x.existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=%. Sample chashes: %. Refusing to overwrite.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- nexus-0rxvg: the quarantine sibling's attributes are copied from the -- ORIGIN's registered row, never parsed from the sibling's own name. The -- catalog-037-1 body split p_quarantine_collection on '__', so for the -- production shape quarantine-<ct>__owner__model__vN the first segment -- carried the prefix and the sibling registered with content_type -- 'quarantine-<ct>' and no dimension -- the defect hygiene-005-1 retired -- in the unbounded twin. PgVectorRepository.quarantineOrphansBounded -- resolves dim from the origin before reaching this function, so an -- unregistered origin is a fail-loud precondition here, as there. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_quarantine_orphans_bounded: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from the quarantine sibling name (nexus-0rxvg, as hygiene-005-1); register the origin before quarantining orphans', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension;
-- created_at CARRIED THROUGH (nexus-a6mon's second finding): the unbounded -- form omits it, so the default restamps every moved row to quarantine time -- and the collection's generation history is destroyed. -- RDR-225: embedding_model rides with the row; the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection), c.created_at, c.embedding_model FROM nexus.chunks c JOIN _a6mon_victim v ON v.chash = c.chash WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection ON CONFLICT (tenant_id, collection, chash, embedding_model) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata, created_at = EXCLUDED.created_at;
WITH del AS ( DELETE FROM nexus.chunks c USING _a6mon_victim v WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = v.chash AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL)) RETURNING c.chash, c.metadata->>'title' AS title ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(chash, 'hex'), 'title', title)) AS s FROM (SELECT chash, title FROM del LIMIT v_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
-- What is LEFT after this commit, so the caller has a terminator it does not -- have to invent from a stalling count. SELECT count(*) INTO v_remaining FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL));
-- nexus-a6mon requirement 5: instrument it. The unbounded form logged only -- the edge's 499 -- no completion line, no timing, nothing between the cut -- and the eventual commit. INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_quarantine_orphans_bounded', p_collection, 'engine', false, v_moved, COALESCE( (SELECT jsonb_agg(elem->>'chash') FROM jsonb_array_elements(COALESCE(v_sample, '[]'::jsonb)) elem), '[]'::jsonb), jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'sample_limit', v_sample_limit, 'row_limit', v_row_limit, 'remaining_after', v_remaining, 'chashes_is_sample', true));
RETURN QUERY SELECT v_moved, v_sample, v_remaining; END; $function$;
-- ---- gc_restore_rereferenced CREATE OR REPLACE FUNCTION nexus.gc_restore_rereferenced(dim integer, p_tenant_id text, p_quarantine_collection text, p_origin_collection text) RETURNS bigint LANGUAGE plpgsql AS $function$ DECLARE v_chashes bytea[]; v_restored bigint := 0; v_row_count bigint := 0; v_collision_count bigint; v_collision_sample text[]; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_restore_rereferenced: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
SELECT array_agg(c.chash) INTO v_chashes FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash );
IF v_chashes IS NULL THEN RETURN 0; END IF;
-- N7-STYLE cross-dim collision guard (Critical-1 fix, T2 [22454]): -- same reasoning as gc_quarantine_orphans's guard -- detect, BEFORE -- any row moves, any restore candidate whose chash already exists at -- p_origin_collection under a DIFFERENT populated embedding_<dim> -- column than the candidate's own. WITH candidate AS ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) ), collision AS ( SELECT cand.chash, cand.src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM candidate cand JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND e.collection = p_origin_collection AND e.chash = cand.chash ) SELECT count(*), COALESCE(array_agg(encode(chash, 'hex') ORDER BY chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM collision WHERE src_dim IS DISTINCT FROM existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_restore_rereferenced: % cross-dim (tenant_id, collection, chash) collision(s) at restore target % for tenant=%, quarantine collection=% -- the unified PK cannot hold two different-dim rows for the same chash (mirrors vectors-004''s N7 guard, T2 22454). Sample chashes: %. Refusing to overwrite; verify the origin-collection naming keeps distinct dims/collections separated before retrying.', v_collision_count, p_origin_collection, p_tenant_id, p_quarantine_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- RDR-204 nexus-uxd2a (hygiene-005-2): NO ENGINE PATH DERIVES A -- COLLECTION'S ATTRIBUTES FROM ITS NAME (coordinator nexus-71 decision, -- same as gc_quarantine_orphans above). p_origin_collection's own name -- usually parsed correctly here (it never carries the quarantine- -- prefix), but deriving from a name is still fragile by construction -- -- an origin name outside the four name-shape branches (hygiene-004's -- underscored-owner class, a two-segment grandfathered name, or -- anything unparseable) silently fell to the 'unknown' stub with no -- dimension ever recorded. This self-registration is a DELIBERATE -- CARVE-OUT (PgVectorRepository.restoreRereferenced's own javadoc, -- RDR-204 Phase 2 nexus-ft04v.16): a genuinely first-ever origin -- collection is still minted here, from real, known attributes -- now -- copied from the QUARANTINE collection's own row rather than parsed -- from either name, since p_quarantine_collection is REQUIRED to -- already be registered (PgVectorRepository.restoreRereferenced -- resolves dim from it before ever reaching this function) and both -- collections share the same embedding space by construction (restore -- only ever moves a chunk between the two). An existing origin row is -- left exactly as it is (ON CONFLICT DO NOTHING) -- only a genuinely -- first-ever origin is minted from the quarantine row's attributes. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_quarantine_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_restore_rereferenced: quarantine collection % is not registered for tenant % -- attributes for a first-ever origin registration are copied from the quarantine row, never parsed from either name (RDR-204 nexus-uxd2a)', p_quarantine_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_origin_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'live' ) ON CONFLICT (tenant_id, name) DO NOTHING;
-- created_at CARRIED THROUGH (nexus-e8h5x review round 2, mirroring -- catalog-037's fix for the opposite direction): the pre-fix INSERT -- omitted it, so the default restamped every restored row to restore -- time and destroyed the chunk's generation history across the -- quarantine round trip. -- RDR-225: embedding_model rides with the row (the chunk's own model, never the origin collection's: an -- origin registered under another model refuses the row at the composite foreign key instead of filing a -- vector under a model that did not embed it); the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model) SELECT p_tenant_id, p_origin_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, (COALESCE(c.metadata, '{}'::jsonb) - 'quarantined_at' - 'origin_collection'), c.created_at, c.embedding_model FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash, embedding_model) DO NOTHING;
-- nexus-brxnp fix round: rows genuinely inserted vs. rows skipped -- because the origin already had a live row for that chash (the DO -- NOTHING conflict) -- recorded below as `already_live` so a -- production investigation can tell the two apart without re-deriving -- it from chunk timestamps by hand (T2 nexus/debug-u6d93-brxnp). GET DIAGNOSTICS v_row_count = ROW_COUNT;
DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes);
v_restored := array_length(v_chashes, 1);
-- nexus-gt03d: audit the restore IN THE SAME TRANSACTION as the DELETE -- above -- this is the exact gap conexus-86/nexus-9la1f found: rows -- leaving quarantine by restore had no forensic trail, unlike -- gc_quarantine_orphans/sweep_superseded_chunks (catalog-033). -- `chashes` here is v_chashes itself (no caller-supplied sample_limit -- on this function, unlike gc_quarantine_orphans -- same shape as -- gc_expire_quarantine's own audit above), truncated at -- GC_AUDIT_MAX_CHASHES (5000, CatalogRepository.java) with -- chash_count still carrying the exact full v_restored count -- regardless of truncation. nexus-brxnp fix round: also -- already_live = candidates that hit the DO NOTHING conflict. INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_restore_rereferenced', p_quarantine_collection, 'engine', false, v_restored, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_chashes[1:LEAST(COALESCE(array_length(v_chashes, 1), 0), 5000)]) x), '[]'::jsonb), jsonb_build_object('origin_collection', p_origin_collection, 'already_live', v_restored - v_row_count) || CASE WHEN COALESCE(array_length(v_chashes, 1), 0) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END );
RETURN v_restored; END; $function$;
-- ---- gc_restore_rereferenced_bounded CREATE OR REPLACE FUNCTION nexus.gc_restore_rereferenced_bounded(dim integer, p_tenant_id text, p_quarantine_collection text, p_origin_collection text, p_row_limit integer) RETURNS TABLE(restored bigint, remaining bigint) LANGUAGE plpgsql AS $function$ DECLARE v_chashes bytea[]; v_restored bigint := 0; v_remaining bigint := 0; v_row_limit int; v_row_count bigint := 0; v_collision_count bigint; v_collision_sample text[]; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- A non-positive bound is a caller error, not "unbounded". The whole -- point of this function is the bound; silently removing it would hand -- back the exact unbounded transaction this exists to prevent (mirrors -- catalog-037's identical guard). IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: p_row_limit must be positive, got %. Use nexus.gc_restore_rereferenced for the unbounded restore.', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
v_row_limit := LEAST(p_row_limit, 100000);
-- THE VICTIM SET, chosen ONCE and ordered for deterministic progress -- across calls (nexus-a6mon's requirement, mirrored here). Unlike -- gc_quarantine_orphans's unbounded form, gc_restore_rereferenced -- ALREADY keys its copy-INSERT and DELETE off one array selected once -- (catalog-039-1's own shape) -- the only change needed to bound it is -- this ORDER BY chash LIMIT on the initial selection. SELECT array_agg(x.chash ORDER BY x.chash) INTO v_chashes FROM ( SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash ) ORDER BY c.chash LIMIT v_row_limit ) x;
IF v_chashes IS NULL THEN RETURN QUERY SELECT 0::bigint, 0::bigint; RETURN; END IF;
-- N7-STYLE cross-dim collision guard (identical to catalog-039-1's, -- scoped to this batch's v_chashes): detect, BEFORE any row moves, any -- restore candidate whose chash already exists at p_origin_collection -- under a DIFFERENT populated embedding_<dim> column than the -- candidate's own. WITH candidate AS ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) ), collision AS ( SELECT cand.chash, cand.src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM candidate cand JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND e.collection = p_origin_collection AND e.chash = cand.chash ) SELECT count(*), COALESCE(array_agg(encode(chash, 'hex') ORDER BY chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM collision WHERE src_dim IS DISTINCT FROM existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: % cross-dim (tenant_id, collection, chash) collision(s) at restore target % for tenant=%, quarantine collection=% -- the unified PK cannot hold two different-dim rows for the same chash (mirrors vectors-004''s N7 guard, T2 22454). Sample chashes: %. Refusing to overwrite; verify the origin-collection naming keeps distinct dims/collections separated before retrying.', v_collision_count, p_origin_collection, p_tenant_id, p_quarantine_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- RDR-204 nexus-uxd2a self-registration (identical to catalog-039-1's): -- a genuinely first-ever origin is minted from the quarantine row's own -- attributes, never parsed from either name. An existing origin row is -- left exactly as it is (ON CONFLICT DO NOTHING). SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_quarantine_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: quarantine collection % is not registered for tenant % -- attributes for a first-ever origin registration are copied from the quarantine row, never parsed from either name (RDR-204 nexus-uxd2a)', p_quarantine_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_origin_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'live' ) ON CONFLICT (tenant_id, name) DO NOTHING;
-- created_at CARRIED THROUGH (nexus-e8h5x, mirroring catalog-037's fix -- for the opposite direction): the unbounded gc_restore_rereferenced's -- INSERT omits it, so the default restamps every restored row to -- restore time and the chunk's generation history through the -- quarantine round trip is lost. -- RDR-225: embedding_model rides with the row (the chunk's own model, never the origin collection's: an -- origin registered under another model refuses the row at the composite foreign key instead of filing a -- vector under a model that did not embed it); the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model) SELECT p_tenant_id, p_origin_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, (COALESCE(c.metadata, '{}'::jsonb) - 'quarantined_at' - 'origin_collection'), c.created_at, c.embedding_model FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes) ON CONFLICT (tenant_id, collection, chash, embedding_model) DO NOTHING;
-- nexus-brxnp fix round: rows genuinely inserted vs. rows skipped -- because the origin already had a live row for that chash (the DO -- NOTHING conflict) -- recorded below as `already_live` so a -- production investigation can tell the two apart without re-deriving -- it from chunk timestamps by hand (T2 nexus/debug-u6d93-brxnp). GET DIAGNOSTICS v_row_count = ROW_COUNT;
DELETE FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND c.chash = ANY(v_chashes);
v_restored := array_length(v_chashes, 1);
-- What is LEFT after this commit, so the caller has a terminator it does -- not have to invent from a stalling count (mirrors catalog-037). SELECT count(*) INTO v_remaining FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = p_origin_collection AND m.chash = c.chash );
-- One gc_audit row per batch, catalog-039-1's audit shape (chashes -- truncated at GC_AUDIT_MAX_CHASHES = 5000, CatalogRepository.java), -- plus row_limit/remaining_after in details, matching catalog-037's -- bounded audit convention. nexus-brxnp fix round: also -- already_live = candidates that hit the DO NOTHING conflict. INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_restore_rereferenced_bounded', p_quarantine_collection, 'engine', false, v_restored, COALESCE( (SELECT jsonb_agg(encode(x, 'hex')) FROM unnest(v_chashes[1:LEAST(COALESCE(array_length(v_chashes, 1), 0), 5000)]) x), '[]'::jsonb), jsonb_build_object( 'origin_collection', p_origin_collection, 'row_limit', v_row_limit, 'remaining_after', v_remaining, 'already_live', v_restored - v_row_count) || CASE WHEN COALESCE(array_length(v_chashes, 1), 0) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END );
RETURN QUERY SELECT v_restored, v_remaining; END; $function$;
-- ---- reaper_quarantine_chunks CREATE OR REPLACE FUNCTION nexus.reaper_quarantine_chunks(p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_row_limit integer, p_grace interval, p_floor_fraction double precision, p_floor_min_chunks integer, p_dry_run boolean) RETURNS TABLE(moved bigint, reapable_count bigint, total_count bigint, refused boolean, remaining bigint) LANGUAGE plpgsql AS $function$ DECLARE v_moved bigint; v_chashes jsonb; v_reapable bigint; v_total bigint; v_row_limit int; v_collision_count bigint; v_collision_sample text[]; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'reaper_quarantine_chunks: p_row_limit must be positive, got %', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF; IF p_floor_fraction IS NULL OR p_floor_fraction < 0 OR p_floor_fraction > 1 OR p_floor_min_chunks IS NULL OR p_floor_min_chunks < 0 THEN RAISE EXCEPTION 'reaper_quarantine_chunks: the floor must be a fraction in [0, 1] and a non-negative minimum, got % / %', p_floor_fraction, p_floor_min_chunks USING ERRCODE = 'invalid_parameter_value'; END IF; v_row_limit := LEAST(p_row_limit, 5000);
IF p_dry_run THEN SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, p_grace))) INTO v_total, v_reapable FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection; RETURN QUERY SELECT 0::bigint, v_reapable, v_total, false, v_reapable; RETURN; END IF;
PERFORM set_config('lock_timeout', '2000', true); PERFORM set_config('statement_timeout', '25000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'reaper_quarantine_chunks: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer holds it; the reaper skips this collection until its next pass', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- Counted again UNDER the gate: the dry run's snapshot may be a pass old, and the floor must be judged -- on what is true while no manifest writer can move the ground. SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, p_grace))) INTO v_total, v_reapable FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection;
IF v_reapable = 0 THEN RETURN QUERY SELECT 0::bigint, 0::bigint, v_total, false, 0::bigint; RETURN; END IF;
-- The floor on the move (see the header). Same shape as gc_expire_quarantine's: at least the minimum, and -- strictly more than the fraction. IF v_reapable >= p_floor_min_chunks AND v_reapable::float8 / v_total::float8 > p_floor_fraction THEN RETURN QUERY SELECT 0::bigint, v_reapable, v_total, true, v_reapable; RETURN; END IF;
-- THE VICTIM SET, chosen once and ordered for deterministic progress. CREATE TEMP TABLE IF NOT EXISTS _x9_victim(chash bytea PRIMARY KEY) ON COMMIT DROP; DELETE FROM _x9_victim; INSERT INTO _x9_victim(chash) SELECT c.chash FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, p_grace)) ORDER BY c.chash LIMIT v_row_limit;
-- Cross-dim collision guard (vectors-004's N7 guard): the unified PK cannot hold two different-dim rows. SELECT count(*), COALESCE(array_agg(encode(x.chash, 'hex') ORDER BY x.chash), '{}'::text[]) INTO v_collision_count, v_collision_sample FROM ( SELECT c.chash, CASE WHEN c.embedding_384 IS NOT NULL THEN 384 WHEN c.embedding_768 IS NOT NULL THEN 768 WHEN c.embedding_1024 IS NOT NULL THEN 1024 END AS src_dim, CASE WHEN e.embedding_384 IS NOT NULL THEN 384 WHEN e.embedding_768 IS NOT NULL THEN 768 WHEN e.embedding_1024 IS NOT NULL THEN 1024 END AS existing_dim FROM nexus.chunks c JOIN _x9_victim v ON v.chash = c.chash JOIN nexus.chunks e ON e.tenant_id = p_tenant_id AND e.collection = p_quarantine_collection AND e.chash = c.chash WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection ) x WHERE x.src_dim IS DISTINCT FROM x.existing_dim;
IF v_collision_count > 0 THEN RAISE EXCEPTION 'reaper_quarantine_chunks: % cross-dim (tenant_id, collection, chash) collision(s) at quarantine target % for tenant=%, origin collection=%. Sample chashes: %. Refusing to overwrite.', v_collision_count, p_quarantine_collection, p_tenant_id, p_collection, v_collision_sample USING ERRCODE = 'unique_violation'; END IF;
-- The sibling's attributes come from the ORIGIN's registered row, never from a name (RDR-204, -- hygiene-005-1). An unregistered origin is a fail-loud precondition. SELECT content_type, owner_id, embedding_model, model_version, dimension INTO v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension FROM nexus.catalog_collections WHERE tenant_id = p_tenant_id AND name = p_collection;
IF NOT FOUND THEN RAISE EXCEPTION 'reaper_quarantine_chunks: origin collection % is not registered for tenant % -- attributes for the quarantine sibling are copied from the origin row, never parsed from a name; register the origin before quarantining chunks', p_collection, p_tenant_id; END IF;
INSERT INTO nexus.catalog_collections (tenant_id, name, content_type, owner_id, embedding_model, model_version, dimension, lifecycle_state) VALUES ( p_tenant_id, p_quarantine_collection, v_origin_content_type, v_origin_owner_id, v_origin_embedding_model, v_origin_model_version, v_origin_dimension, 'quarantine' ) ON CONFLICT (tenant_id, name) DO UPDATE SET content_type = EXCLUDED.content_type, owner_id = EXCLUDED.owner_id, embedding_model = EXCLUDED.embedding_model, model_version = EXCLUDED.model_version, dimension = EXCLUDED.dimension;
-- The move: DELETE with the predicate in its own WHERE, copy through RETURNING, one statement. A chunk a -- client refreshed after the victim set was chosen fails the recheck, is not deleted, and is not copied. WITH del AS ( DELETE FROM nexus.chunks c USING _x9_victim v WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = v.chash AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, p_grace)) RETURNING c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, c.metadata, c.created_at, c.embedding_model ), copied AS ( -- RDR-225: the moved row keeps its embedding_model (the quarantine sibling is registered under the -- origin's model above); the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, embedding_model) SELECT p_tenant_id, p_quarantine_collection, d.chash, d.chunk_text, d.embedding_384, d.embedding_768, d.embedding_1024, COALESCE(d.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection, 'quarantined_by', 'engine-reaper', 'reaper_quarantined_at', p_quarantined_at), d.created_at, d.embedding_model FROM del d ON CONFLICT (tenant_id, collection, chash, embedding_model) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata, created_at = EXCLUDED.created_at RETURNING 1 ) SELECT count(*), COALESCE(jsonb_agg(encode(d.chash, 'hex')), '[]'::jsonb) INTO v_moved, v_chashes FROM del d;
IF v_moved > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'reaper_quarantine', p_collection, 'engine-reaper', false, v_moved, v_chashes, jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'row_limit', v_row_limit, 'grace', COALESCE(p_grace::text, 'default'), 'floor_fraction', p_floor_fraction, 'floor_min_chunks', p_floor_min_chunks, 'reapable_before', v_reapable, 'total_before', v_total, 'remaining_after', GREATEST(v_reapable - v_moved, 0))); END IF;
RETURN QUERY SELECT v_moved, v_reapable, v_total, false, GREATEST(v_reapable - v_moved, 0); END; $function$;
-- ---- quarantine_restore_chunks CREATE OR REPLACE FUNCTION nexus.quarantine_restore_chunks(p_tenant_id text, p_origin_collection text, p_quarantine_collection text, p_chashes text[], p_actor text, p_source_audit_id bigint, p_dry_run boolean, p_reattach boolean) RETURNS TABLE(r_chash text, r_outcome text, r_audit_id bigint, r_no_manifest boolean, r_reapable_after timestamp with time zone, r_reattach text, r_attached boolean, r_owner text, r_owner_title text, r_position integer, r_chunk_title text, r_reason text, r_owner_rows integer, r_owner_chunks integer) LANGUAGE plpgsql AS $function$ DECLARE -- The default grace of the reapable predicate (vectors-021-2), for the report only; see the header. v_default_grace CONSTANT interval := interval '30 days'; v_now timestamptz := now(); v_requested text[]; v_class jsonb; v_plan jsonb := '[]'::jsonb; v_cand text[]; v_doc text; v_restored text[] := '{}'::text[]; v_present text[]; v_dim_conflict text[]; v_missing text[]; v_no_manifest text[]; v_attached text[] := '{}'::text[]; v_superseded text[]; v_no_owner text[]; v_no_position text[]; v_audit_chashes text[]; v_audit_id bigint; v_actor text; BEGIN IF p_chashes IS NULL OR cardinality(p_chashes) = 0 THEN RAISE EXCEPTION 'quarantine_restore_chunks: at least one chash is required' USING ERRCODE = 'invalid_parameter_value'; END IF; IF cardinality(p_chashes) > 5000 THEN RAISE EXCEPTION 'quarantine_restore_chunks: at most 5000 chashes per call, got %', cardinality(p_chashes) USING ERRCODE = 'invalid_parameter_value'; END IF; IF EXISTS (SELECT 1 FROM unnest(p_chashes) h WHERE h IS NULL OR h !~ '^[0-9a-f]{64}$') THEN RAISE EXCEPTION 'quarantine_restore_chunks: every chash must be 64 lowercase hex characters' USING ERRCODE = 'invalid_parameter_value'; END IF; IF p_origin_collection IS NULL OR p_origin_collection = '' OR left(p_origin_collection, 11) = 'quarantine-' THEN RAISE EXCEPTION 'quarantine_restore_chunks: the origin collection must be a non-quarantine collection, got %', p_origin_collection USING ERRCODE = 'invalid_parameter_value'; END IF; IF NOT EXISTS (SELECT 1 FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection AND cc.lifecycle_state = 'live') THEN RAISE EXCEPTION 'quarantine_restore_chunks: origin collection % is not a registered live collection for tenant % -- a chunk is restored into a registered live collection, never into a name', p_origin_collection, p_tenant_id USING ERRCODE = 'invalid_parameter_value'; END IF; IF NOT EXISTS (SELECT 1 FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection AND cc.lifecycle_state = 'quarantine') THEN RAISE EXCEPTION 'quarantine_restore_chunks: % is not a registered quarantine collection for tenant %', p_quarantine_collection, p_tenant_id USING ERRCODE = 'invalid_parameter_value'; END IF;
-- The distinct requested chashes in first-seen order: the result carries one row per chash. SELECT array_agg(x.h ORDER BY x.ord) INTO v_requested FROM (SELECT u.h, min(u.ord) AS ord FROM unnest(p_chashes) WITH ORDINALITY AS u(h, ord) GROUP BY u.h) x;
IF p_dry_run THEN SELECT jsonb_agg(jsonb_build_object('h', x.h, 'outcome', x.outcome) ORDER BY x.ord) INTO v_class FROM ( SELECT r.h, r.ord, CASE WHEN o.chash IS NOT NULL AND q.chash IS NOT NULL AND (CASE WHEN o.embedding_384 IS NOT NULL THEN 384 WHEN o.embedding_768 IS NOT NULL THEN 768 WHEN o.embedding_1024 IS NOT NULL THEN 1024 END) IS DISTINCT FROM (CASE WHEN q.embedding_384 IS NOT NULL THEN 384 WHEN q.embedding_768 IS NOT NULL THEN 768 WHEN q.embedding_1024 IS NOT NULL THEN 1024 END) THEN 'dim_conflict' WHEN o.chash IS NOT NULL THEN 'present' WHEN q.chash IS NOT NULL THEN 'would_restore' ELSE 'missing' END AS outcome FROM unnest(v_requested) WITH ORDINALITY AS r(h, ord) LEFT JOIN nexus.chunks o ON o.tenant_id = p_tenant_id AND o.collection = p_origin_collection AND o.chash = decode(r.h, 'hex') LEFT JOIN nexus.chunks q ON q.tenant_id = p_tenant_id AND q.collection = p_quarantine_collection AND q.chash = decode(r.h, 'hex') AND COALESCE(q.metadata->>'origin_collection', p_origin_collection) = p_origin_collection ) x; v_plan := nexus.quarantine_reattach_plan(p_tenant_id, p_origin_collection, p_quarantine_collection, ARRAY(SELECT t.j->>'h' FROM jsonb_array_elements(v_class) AS t(j) WHERE t.j->>'outcome' IN ('would_restore', 'present')), true); RETURN QUERY SELECT t.j->>'h', t.j->>'outcome', NULL::bigint, NULL::boolean, NULL::timestamptz, pl.verdict, false, pl.doc, pl.title, pl.pos, pl.chunk_title, pl.why, oc.n_rows, oc.n_chunks FROM jsonb_array_elements(v_class) WITH ORDINALITY AS t(j, ord) LEFT JOIN jsonb_to_recordset(v_plan) AS pl(chash text, verdict text, why text, doc text, title text, pos integer, chunk_title text) ON pl.chash = t.j->>'h' LEFT JOIN LATERAL ( SELECT (SELECT count(*) FROM nexus.catalog_document_chunks m WHERE m.tenant_id = p_tenant_id AND m.doc_id = pl.doc AND m.collection = p_origin_collection)::integer AS n_rows, (SELECT d.chunk_count FROM nexus.catalog_documents d WHERE d.tenant_id = p_tenant_id AND d.tumbler = pl.doc) AS n_chunks) oc ON pl.doc IS NOT NULL ORDER BY t.ord; RETURN; END IF;
PERFORM set_config('lock_timeout', '2000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_origin_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'quarantine_restore_chunks: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer holds it; retry', p_tenant_id, p_origin_collection USING ERRCODE = 'lock_not_available'; END;
-- THE MOVE: one statement, vectors-024's reaper_quarantine_chunks in reverse. The DELETE's WHERE skips a chash -- the origin already has (it is not deleted, so it stays in quarantine); the INSERT takes last_written_at = now() -- (see the header) and the carried created_at; ON CONFLICT DO NOTHING is the single-statement race's backstop. WITH req AS ( SELECT decode(r.h, 'hex') AS chash FROM unnest(v_requested) AS r(h) ), del AS ( DELETE FROM nexus.chunks q USING req WHERE q.tenant_id = p_tenant_id AND q.collection = p_quarantine_collection AND q.chash = req.chash AND COALESCE(q.metadata->>'origin_collection', p_origin_collection) = p_origin_collection AND NOT EXISTS (SELECT 1 FROM nexus.chunks o WHERE o.tenant_id = p_tenant_id AND o.collection = p_origin_collection AND o.chash = q.chash) RETURNING q.chash, q.chunk_text, q.embedding_384, q.embedding_768, q.embedding_1024, q.metadata, q.created_at, q.embedding_model ), ins AS ( -- RDR-225: the chunk's own embedding_model rides with the move (an origin registered under another -- model refuses it at the composite foreign key); the arbiter is the four-column primary key. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, created_at, last_written_at, embedding_model) SELECT p_tenant_id, p_origin_collection, d.chash, d.chunk_text, d.embedding_384, d.embedding_768, d.embedding_1024, (COALESCE(d.metadata, '{}'::jsonb) - 'quarantined_at' - 'origin_collection' - 'quarantined_by' - 'reaper_quarantined_at'), d.created_at, v_now, d.embedding_model FROM del d ON CONFLICT (tenant_id, collection, chash, embedding_model) DO NOTHING RETURNING chash ) SELECT COALESCE(array_agg(encode(i.chash, 'hex') ORDER BY i.chash), '{}'::text[]) INTO v_restored FROM ins i;
-- Everything not restored is already in the origin (present, or dim_conflict when the quarantine copy is still -- there and holds a different width) or nowhere (missing). SELECT COALESCE(array_agg(c.h ORDER BY c.ord) FILTER (WHERE c.has_o AND NOT c.dim_differs), '{}'::text[]), COALESCE(array_agg(c.h ORDER BY c.ord) FILTER (WHERE c.has_o AND c.dim_differs), '{}'::text[]), COALESCE(array_agg(c.h ORDER BY c.ord) FILTER (WHERE NOT c.has_o), '{}'::text[]) INTO v_present, v_dim_conflict, v_missing FROM ( SELECT r.h, r.ord, o.chash IS NOT NULL AS has_o, (o.chash IS NOT NULL AND q.chash IS NOT NULL AND (CASE WHEN o.embedding_384 IS NOT NULL THEN 384 WHEN o.embedding_768 IS NOT NULL THEN 768 WHEN o.embedding_1024 IS NOT NULL THEN 1024 END) IS DISTINCT FROM (CASE WHEN q.embedding_384 IS NOT NULL THEN 384 WHEN q.embedding_768 IS NOT NULL THEN 768 WHEN q.embedding_1024 IS NOT NULL THEN 1024 END)) AS dim_differs FROM unnest(v_requested) WITH ORDINALITY AS r(h, ord) LEFT JOIN nexus.chunks o ON o.tenant_id = p_tenant_id AND o.collection = p_origin_collection AND o.chash = decode(r.h, 'hex') LEFT JOIN nexus.chunks q ON q.tenant_id = p_tenant_id AND q.collection = p_quarantine_collection AND q.chash = decode(r.h, 'hex') AND COALESCE(q.metadata->>'origin_collection', p_origin_collection) = p_origin_collection WHERE NOT (r.h = ANY (v_restored)) ) c;
-- REATTACH. The candidates are the chunks now in the origin that this call named and that are not a width -- conflict: the ones it restored and the ones that were already there. v_cand := v_restored || v_present; IF cardinality(v_cand) > 0 THEN v_plan := nexus.quarantine_reattach_plan(p_tenant_id, p_origin_collection, p_quarantine_collection, v_cand, false); IF p_reattach THEN -- The per-document index-run lock manifest writers take, in tumbler order so two restores cannot -- deadlock, then the plan again under it: what is written is what was judged under the lock. FOR v_doc IN SELECT DISTINCT pl.doc FROM jsonb_to_recordset(v_plan) AS pl(chash text, verdict text, doc text) WHERE pl.doc IS NOT NULL ORDER BY pl.doc LOOP PERFORM pg_advisory_xact_lock(hashtext('indexrun:' || p_tenant_id || ':' || v_doc)); END LOOP; v_plan := nexus.quarantine_reattach_plan(p_tenant_id, p_origin_collection, p_quarantine_collection, v_cand, false);
WITH ins AS ( -- RDR-225: the manifest row carries the origin collection's embedding_model, the model its -- chunk rows carry (one model per collection), so the four-column chunk foreign key holds. INSERT INTO nexus.catalog_document_chunks (tenant_id, doc_id, position, chash, chunk_index, line_start, line_end, char_start, char_end, collection, embedding_model) SELECT p_tenant_id, pl.doc, pl.pos, decode(pl.chash, 'hex'), pl.pos, pl.ls, pl.le, pl.cs, pl.ce, p_origin_collection, (SELECT oc.embedding_model FROM nexus.catalog_collections oc WHERE oc.tenant_id = p_tenant_id AND oc.name = p_origin_collection) FROM jsonb_to_recordset(v_plan) AS pl(chash text, verdict text, doc text, pos integer, ls integer, le integer, cs integer, ce integer) WHERE pl.verdict = 'attach' ON CONFLICT (tenant_id, doc_id, position) DO NOTHING RETURNING chash ) SELECT COALESCE(array_agg(encode(i.chash, 'hex') ORDER BY i.chash), '{}'::text[]) INTO v_attached FROM ins i; END IF; END IF;
-- What reattach left alone, by reason; a chunk the plan would have attached but whose insert lost a race -- (cannot happen under the gate and the document lock, but the report must not claim it) reads superseded. SELECT COALESCE(array_agg(pl.chash ORDER BY pl.chash) FILTER (WHERE pl.verdict = 'superseded' OR (pl.verdict = 'attach' AND p_reattach AND NOT (pl.chash = ANY (v_attached)))), '{}'::text[]), COALESCE(array_agg(pl.chash ORDER BY pl.chash) FILTER (WHERE pl.verdict = 'no_live_owner'), '{}'::text[]), COALESCE(array_agg(pl.chash ORDER BY pl.chash) FILTER (WHERE pl.verdict = 'no_position'), '{}'::text[]) INTO v_superseded, v_no_owner, v_no_position FROM jsonb_to_recordset(v_plan) AS pl(chash text, verdict text);
-- Restored chunks with no own-collection manifest row AFTER the attach: hidden, and reapable again at -- v_now + the default grace. SELECT COALESCE(array_agg(r.h ORDER BY r.h), '{}'::text[]) INTO v_no_manifest FROM unnest(v_restored) AS r(h) WHERE NOT EXISTS (SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = p_tenant_id AND m.collection = p_origin_collection AND m.chash = decode(r.h, 'hex'));
v_actor := COALESCE(NULLIF(left(btrim(p_actor), 256), ''), 'operator'); v_audit_chashes := ARRAY(SELECT x FROM unnest(v_restored || v_attached) AS x GROUP BY x ORDER BY x);
IF cardinality(v_audit_chashes) > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'quarantine_restore', p_origin_collection, v_actor, false, cardinality(v_audit_chashes), to_jsonb(v_audit_chashes), jsonb_build_object( 'quarantine_collection', p_quarantine_collection, 'source_audit_id', p_source_audit_id, 'requested', cardinality(v_requested), 'restored', cardinality(v_restored), 'present', cardinality(v_present), 'dim_conflict', cardinality(v_dim_conflict), 'missing', cardinality(v_missing), 'present_chashes', to_jsonb(v_present), 'dim_conflict_chashes', to_jsonb(v_dim_conflict), 'missing_chashes', to_jsonb(v_missing), 'no_manifest', cardinality(v_no_manifest), 'reattach', p_reattach, 'attached', cardinality(v_attached), 'attached_chashes', to_jsonb(v_attached), 'superseded', cardinality(v_superseded), 'superseded_chashes', to_jsonb(v_superseded), 'no_live_owner', cardinality(v_no_owner), 'no_live_owner_chashes', to_jsonb(v_no_owner), 'no_position', cardinality(v_no_position), 'no_position_chashes', to_jsonb(v_no_position), 'reapable_again_after', to_char((v_now + v_default_grace) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'))) RETURNING id INTO v_audit_id; END IF;
RETURN QUERY SELECT r.h, CASE WHEN r.h = ANY (v_restored) THEN 'restored' WHEN r.h = ANY (v_dim_conflict) THEN 'dim_conflict' WHEN r.h = ANY (v_present) THEN 'present' ELSE 'missing' END, CASE WHEN r.h = ANY (v_audit_chashes) THEN v_audit_id END, CASE WHEN r.h = ANY (v_restored) THEN r.h = ANY (v_no_manifest) END, CASE WHEN r.h = ANY (v_no_manifest) THEN v_now + v_default_grace END, CASE WHEN pl.verdict = 'attach' AND p_reattach AND NOT (r.h = ANY (v_attached)) THEN 'superseded' ELSE pl.verdict END, (r.h = ANY (v_attached)), pl.doc, pl.title, pl.pos, pl.chunk_title, CASE WHEN pl.verdict = 'attach' AND p_reattach AND NOT (r.h = ANY (v_attached)) THEN 'race' ELSE pl.why END, oc.n_rows, oc.n_chunks FROM unnest(v_requested) WITH ORDINALITY AS r(h, ord) LEFT JOIN jsonb_to_recordset(v_plan) AS pl(chash text, verdict text, why text, doc text, title text, pos integer, chunk_title text) ON pl.chash = r.h LEFT JOIN LATERAL ( SELECT (SELECT count(*) FROM nexus.catalog_document_chunks m WHERE m.tenant_id = p_tenant_id AND m.doc_id = pl.doc AND m.collection = p_origin_collection)::integer AS n_rows, (SELECT d.chunk_count FROM nexus.catalog_documents d WHERE d.tenant_id = p_tenant_id AND d.tumbler = pl.doc) AS n_chunks) oc ON pl.doc IS NOT NULL ORDER BY r.ord; END; $function$;
-- ---- assign_from_chashes_384 CREATE OR REPLACE FUNCTION nexus.assign_from_chashes_384(p_collection text, p_chashes text[], p_cross_collection boolean) RETURNS TABLE(chash text, topic_id bigint, similarity double precision) LANGUAGE plpgsql AS $function$ #variable_conflict use_column BEGIN IF p_cross_collection THEN -- Sam's standing rule for this RDR: one fail-loud path for every -- stub-insert, nothing mints a catalog_collections row from a name -- any more. Post-nexus-ft04v.7, chunks_collection_fk already requires -- p_collection to be registered before any chunk can exist under it, -- so if the batch below finds rows at all, the row is guaranteed -- present -- this guard only ever fires on a genuinely absent -- registration (a caller naming a collection with zero chunks), and -- names the remedy instead of silently minting the row this branch -- used to stub-insert here. IF NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections WHERE tenant_id = current_setting('nexus.tenant', true) AND name = p_collection ) THEN RAISE EXCEPTION 'assign_from_chashes_384: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert', p_collection, current_setting('nexus.tenant', true) USING ERRCODE = 'foreign_key_violation'; END IF;
-- nexus-f3yxx: the LATERAL's recall settings, transaction-local. -- NOT a function-level SET clause: CREATE FUNCTION ... SET hnsw.* -- fails with 'permission denied to set parameter' for a -- non-superuser migration role when pgvector's library is not yet -- loaded in that session (hnsw.* is then an unknown placeholder), -- which is every production boot (candidate-migration leg, -- 2026-09-25). set_config is allowed to any role. is_local=true -- scopes it to this transaction, which since the rework is the -- cross pass alone. PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true);
-- nexus-swam7: pin the ACCESS PATH itself, not just the ANN recall -- settings. At ef_search=400 the planner's own cost model prefers a -- per-chunk Seq Scan + top-N Sort over taxonomy_centroids until -- ~8,000 centroids/dim (T2 nexus/p02-hnsw-incremental-recall- -- 2026-09-25); below that, this pin is what makes the "measured -- equal to exact at ef400" claim (taxonomy-018's header) actually -- true, by forcing the HNSW index scan the recall claim assumes. -- Legal as a function-level SET (these are core GUCs, unlike -- hnsw.*), but kept as set_config for consistency with the two -- calls above -- see this changeset's own header for the full -- reasoning and the measurement that verified each pin's effect. PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_384 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.collection <> p_collection AND ct.embedding_model = b.b_model AND ct.embedding_384 IS NOT NULL ORDER BY ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ), persisted AS ( -- RDR-225: embedding_model is the chunk's own (it is part of the four-column chunk foreign key). INSERT INTO nexus.topic_assignments AS ta (tenant_id, doc_id, topic_id, assigned_by, similarity, assigned_at, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'projection', n.m_sim, now(), p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO UPDATE SET similarity = GREATEST(COALESCE(ta.similarity, -1.0), EXCLUDED.similarity), assigned_at = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.assigned_at ELSE ta.assigned_at END, source_collection = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection ELSE ta.source_collection END, -- the model moves with the source collection: the pair is one chunk reference. embedding_model = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.embedding_model ELSE ta.embedding_model END, assigned_by = 'projection' RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; ELSE RETURN QUERY WITH nearest AS ( SELECT DISTINCT ON (c.chash) encode(c.chash, 'hex') AS m_chash, c.chash AS m_chash_bytes, c.embedding_model AS m_model, ct.topic_id AS m_topic_id, (1 - (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384))::double precision AS m_sim FROM nexus.chunks c JOIN nexus.taxonomy_centroids ct ON ct.collection = p_collection AND ct.embedding_384 IS NOT NULL WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ORDER BY c.chash, (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384) ASC, ct.topic_id ASC ), persisted AS ( INSERT INTO nexus.topic_assignments (tenant_id, doc_id, topic_id, assigned_by, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'centroid', p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $function$;
-- ---- assign_from_chashes_768 CREATE OR REPLACE FUNCTION nexus.assign_from_chashes_768(p_collection text, p_chashes text[], p_cross_collection boolean) RETURNS TABLE(chash text, topic_id bigint, similarity double precision) LANGUAGE plpgsql AS $function$ #variable_conflict use_column BEGIN IF p_cross_collection THEN IF NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections WHERE tenant_id = current_setting('nexus.tenant', true) AND name = p_collection ) THEN RAISE EXCEPTION 'assign_from_chashes_768: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert', p_collection, current_setting('nexus.tenant', true) USING ERRCODE = 'foreign_key_violation'; END IF;
-- nexus-f3yxx: the LATERAL's recall settings, transaction-local. -- NOT a function-level SET clause: CREATE FUNCTION ... SET hnsw.* -- fails with 'permission denied to set parameter' for a -- non-superuser migration role when pgvector's library is not yet -- loaded in that session (hnsw.* is then an unknown placeholder), -- which is every production boot (candidate-migration leg, -- 2026-09-25). set_config is allowed to any role. is_local=true -- scopes it to this transaction, which since the rework is the -- cross pass alone. PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true);
-- nexus-swam7: pin the ACCESS PATH itself, not just the ANN recall -- settings. At ef_search=400 the planner's own cost model prefers a -- per-chunk Seq Scan + top-N Sort over taxonomy_centroids until -- ~8,000 centroids/dim (T2 nexus/p02-hnsw-incremental-recall- -- 2026-09-25); below that, this pin is what makes the "measured -- equal to exact at ef400" claim (taxonomy-018's header) actually -- true, by forcing the HNSW index scan the recall claim assumes. -- Legal as a function-level SET (these are core GUCs, unlike -- hnsw.*), but kept as set_config for consistency with the two -- calls above -- see this changeset's own header for the full -- reasoning and the measurement that verified each pin's effect. PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_768 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_768 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_768 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.collection <> p_collection AND ct.embedding_model = b.b_model AND ct.embedding_768 IS NOT NULL ORDER BY ct.embedding_768 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ), persisted AS ( -- RDR-225: embedding_model is the chunk's own (it is part of the four-column chunk foreign key). INSERT INTO nexus.topic_assignments AS ta (tenant_id, doc_id, topic_id, assigned_by, similarity, assigned_at, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'projection', n.m_sim, now(), p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO UPDATE SET similarity = GREATEST(COALESCE(ta.similarity, -1.0), EXCLUDED.similarity), assigned_at = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.assigned_at ELSE ta.assigned_at END, source_collection = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection ELSE ta.source_collection END, -- the model moves with the source collection: the pair is one chunk reference. embedding_model = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.embedding_model ELSE ta.embedding_model END, assigned_by = 'projection' RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; ELSE RETURN QUERY WITH nearest AS ( SELECT DISTINCT ON (c.chash) encode(c.chash, 'hex') AS m_chash, c.chash AS m_chash_bytes, c.embedding_model AS m_model, ct.topic_id AS m_topic_id, (1 - (c.embedding_768 OPERATOR(nexus.<=>) ct.embedding_768))::double precision AS m_sim FROM nexus.chunks c JOIN nexus.taxonomy_centroids ct ON ct.collection = p_collection AND ct.embedding_768 IS NOT NULL WHERE c.collection = p_collection AND c.embedding_768 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ORDER BY c.chash, (c.embedding_768 OPERATOR(nexus.<=>) ct.embedding_768) ASC, ct.topic_id ASC ), persisted AS ( INSERT INTO nexus.topic_assignments (tenant_id, doc_id, topic_id, assigned_by, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'centroid', p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $function$;
-- ---- assign_from_chashes_1024 CREATE OR REPLACE FUNCTION nexus.assign_from_chashes_1024(p_collection text, p_chashes text[], p_cross_collection boolean) RETURNS TABLE(chash text, topic_id bigint, similarity double precision) LANGUAGE plpgsql AS $function$ #variable_conflict use_column BEGIN IF p_cross_collection THEN IF NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections WHERE tenant_id = current_setting('nexus.tenant', true) AND name = p_collection ) THEN RAISE EXCEPTION 'assign_from_chashes_1024: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert', p_collection, current_setting('nexus.tenant', true) USING ERRCODE = 'foreign_key_violation'; END IF;
-- nexus-f3yxx: the LATERAL's recall settings, transaction-local. -- NOT a function-level SET clause: CREATE FUNCTION ... SET hnsw.* -- fails with 'permission denied to set parameter' for a -- non-superuser migration role when pgvector's library is not yet -- loaded in that session (hnsw.* is then an unknown placeholder), -- which is every production boot (candidate-migration leg, -- 2026-09-25). set_config is allowed to any role. is_local=true -- scopes it to this transaction, which since the rework is the -- cross pass alone. PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true);
-- nexus-swam7: pin the ACCESS PATH itself, not just the ANN recall -- settings. At ef_search=400 the planner's own cost model prefers a -- per-chunk Seq Scan + top-N Sort over taxonomy_centroids until -- ~8,000 centroids/dim (T2 nexus/p02-hnsw-incremental-recall- -- 2026-09-25); below that, this pin is what makes the "measured -- equal to exact at ef400" claim (taxonomy-018's header) actually -- true, by forcing the HNSW index scan the recall claim assumes. -- Legal as a function-level SET (these are core GUCs, unlike -- hnsw.*), but kept as set_config for consistency with the two -- calls above -- see this changeset's own header for the full -- reasoning and the measurement that verified each pin's effect. PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_1024 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_1024 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_1024 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.collection <> p_collection AND ct.embedding_model = b.b_model AND ct.embedding_1024 IS NOT NULL ORDER BY ct.embedding_1024 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ), persisted AS ( -- RDR-225: embedding_model is the chunk's own (it is part of the four-column chunk foreign key). INSERT INTO nexus.topic_assignments AS ta (tenant_id, doc_id, topic_id, assigned_by, similarity, assigned_at, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'projection', n.m_sim, now(), p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO UPDATE SET similarity = GREATEST(COALESCE(ta.similarity, -1.0), EXCLUDED.similarity), assigned_at = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.assigned_at ELSE ta.assigned_at END, source_collection = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection ELSE ta.source_collection END, -- the model moves with the source collection: the pair is one chunk reference. embedding_model = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.embedding_model ELSE ta.embedding_model END, assigned_by = 'projection' RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; ELSE RETURN QUERY WITH nearest AS ( SELECT DISTINCT ON (c.chash) encode(c.chash, 'hex') AS m_chash, c.chash AS m_chash_bytes, c.embedding_model AS m_model, ct.topic_id AS m_topic_id, (1 - (c.embedding_1024 OPERATOR(nexus.<=>) ct.embedding_1024))::double precision AS m_sim FROM nexus.chunks c JOIN nexus.taxonomy_centroids ct ON ct.collection = p_collection AND ct.embedding_1024 IS NOT NULL WHERE c.collection = p_collection AND c.embedding_1024 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ORDER BY c.chash, (c.embedding_1024 OPERATOR(nexus.<=>) ct.embedding_1024) ASC, ct.topic_id ASC ), persisted AS ( INSERT INTO nexus.topic_assignments (tenant_id, doc_id, topic_id, assigned_by, source_collection, embedding_model) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'centroid', p_collection, n.m_model FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $function$;
-- ---- cross_preview_384 CREATE OR REPLACE FUNCTION nexus.cross_preview_384( p_collection text, p_chashes text[] ) RETURNS TABLE( chash text, topic_id bigint, similarity double precision ) LANGUAGE plpgsql SECURITY INVOKER AS $function$ #variable_conflict use_column BEGIN -- nexus-v4pj4: read-only twin of assign_from_chashes_384's cross -- branch (taxonomy-020-1). Same four transaction-local settings; -- see that changeset's header for the full reasoning. NEVER writes -- to topic_assignments. -- RDR-225: the batch/nearest CTE is byte-identical to assign_from_chashes_<dim>'s cross branch (CrossPreviewDriftTest), -- which now carries the chunk's embedding_model for the persist; the preview selects it and does not persist it. Both match centroids of the chunk's own model only. PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true); PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_384 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.collection <> p_collection AND ct.embedding_model = b.b_model AND ct.embedding_384 IS NOT NULL ORDER BY ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; END; $function$;
-- ---- cross_preview_768 CREATE OR REPLACE FUNCTION nexus.cross_preview_768( p_collection text, p_chashes text[] ) RETURNS TABLE( chash text, topic_id bigint, similarity double precision ) LANGUAGE plpgsql SECURITY INVOKER AS $function$ #variable_conflict use_column BEGIN PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true); PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_768 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_768 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_768 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.collection <> p_collection AND ct.embedding_model = b.b_model AND ct.embedding_768 IS NOT NULL ORDER BY ct.embedding_768 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; END; $function$;
-- ---- cross_preview_1024 CREATE OR REPLACE FUNCTION nexus.cross_preview_1024( p_collection text, p_chashes text[] ) RETURNS TABLE( chash text, topic_id bigint, similarity double precision ) LANGUAGE plpgsql SECURITY INVOKER AS $function$ #variable_conflict use_column BEGIN PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true); PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_1024 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_1024 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_1024 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.collection <> p_collection AND ct.embedding_model = b.b_model AND ct.embedding_1024 IS NOT NULL ORDER BY ct.embedding_1024 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; END; $function$;
-- ---- stamp_chunks_on_manifest_delete CREATE OR REPLACE FUNCTION nexus.stamp_chunks_on_manifest_delete() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN -- Lock the chunk rows first, in key order: two writers that drop the last two owners of a shared -- chunk serialize here (the second blocks until the first commits, then reads its committed -- orphaned_at), and writers that share several chunks take their locks in the same order, so two -- of these triggers cannot deadlock on chunk rows. The key list is the same as the upsert's. PERFORM 1 FROM nexus.chunks c JOIN (SELECT DISTINCT tenant_id, collection, chash, embedding_model FROM old_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model WHERE c.last_written_at < now() - interval '1 hour' ORDER BY c.tenant_id, c.collection, c.chash FOR NO KEY UPDATE OF c;
-- Record the orphaning. The one-hour guard: a chunk written within the hour is skipped here -- (the select filters on last_written_at) and a chunk already recorded within the hour is -- skipped by the DO UPDATE's WHERE. Driven from the chunk rows, so a key with no chunk (the -- foreign key would refuse it) records nothing. -- RDR-225: the orphaned-at row carries the chunk's embedding_model (the four-column chunk foreign key); -- its own primary key, and so this arbiter, stays (tenant_id, collection, chash). INSERT INTO nexus.chunk_orphaned_at AS q (tenant_id, collection, chash, orphaned_at, embedding_model) SELECT c.tenant_id, c.collection, c.chash, now(), c.embedding_model FROM nexus.chunks c JOIN (SELECT DISTINCT tenant_id, collection, chash, embedding_model FROM old_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model WHERE c.last_written_at < now() - interval '1 hour' ORDER BY c.tenant_id, c.collection, c.chash ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET orphaned_at = EXCLUDED.orphaned_at WHERE q.orphaned_at < now() - interval '1 hour'; RETURN NULL; END; $function$;
-- ---- stamp_chunks_on_manifest_update CREATE OR REPLACE FUNCTION nexus.stamp_chunks_on_manifest_update() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN -- The keys the statement dropped are the old keys minus the new keys: a row that keeps its -- (tenant, collection, chash), whatever else changed, drops nothing; one that moves position and -- chash together drops the old chash. Same lock, same upsert, same guard as the DELETE trigger. PERFORM 1 FROM nexus.chunks c JOIN (SELECT tenant_id, collection, chash, embedding_model FROM old_rows EXCEPT SELECT tenant_id, collection, chash, embedding_model FROM new_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model WHERE c.last_written_at < now() - interval '1 hour' ORDER BY c.tenant_id, c.collection, c.chash FOR NO KEY UPDATE OF c;
-- RDR-225: carries the chunk's embedding_model; the arbiter stays the table's own three-column key. INSERT INTO nexus.chunk_orphaned_at AS q (tenant_id, collection, chash, orphaned_at, embedding_model) SELECT c.tenant_id, c.collection, c.chash, now(), c.embedding_model FROM nexus.chunks c JOIN (SELECT tenant_id, collection, chash, embedding_model FROM old_rows EXCEPT SELECT tenant_id, collection, chash, embedding_model FROM new_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model WHERE c.last_written_at < now() - interval '1 hour' ORDER BY c.tenant_id, c.collection, c.chash ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET orphaned_at = EXCLUDED.orphaned_at WHERE q.orphaned_at < now() - interval '1 hour'; RETURN NULL; END; $function$;
-- ---- purge_trash CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval) RETURNS bigint LANGUAGE plpgsql SET search_path TO 'nexus', 'public' AS $function$ DECLARE v_tenant TEXT; v_count BIGINT; v_chunk_count BIGINT; v_chunk_sample jsonb; BEGIN -- GUC guard: must have a non-empty tenant scope v_tenant := current_setting('nexus.tenant', true); IF v_tenant IS NULL OR v_tenant = '' THEN RAISE EXCEPTION 'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. ' 'Cross-tenant purge is not permitted. Set the nexus.tenant configuration ' 'parameter before calling purge_trash.'; END IF;
-- RDR-191 Phase 5 (nexus-o8dil.29, class-B site 1): fk_catalog_chunks_chunk is -- DEFERRABLE INITIALLY IMMEDIATE (catalog-029-0). Step 1 below deletes FROM -- nexus.chunks while its referencing catalog_document_chunks rows still exist -- (removed only in Step 4, later in this same transaction) -- defer the check -- to this call's COMMIT, by which point Step 4 has cascaded them away. -- RDR-225: schema-qualified. A bare constraint name resolves through the search_path, and the walk -- connection's search_path is public, so the qualified name is the one that always resolves. SET CONSTRAINTS nexus.fk_catalog_chunks_chunk DEFERRED;
-- Step 1-3 (collapsed): sweep orphaned chunk rows from the unified -- nexus.chunks. Safety contract unchanged from catalog-026-1: a chunk -- is sweepable ONLY IF it has at least one manifest row in ITS OWN -- collection AND none of ITS OWN collection's manifest rows PROTECT it -- -- a row protects when its owning document is LIVE, or TOMBSTONED but -- still inside the older_than grace window. GH #1546 (nexus-ky9ps): both -- manifest matches below are now scoped to `m.collection = c.collection` -- -- an identical chash under a live document in a DIFFERENT collection -- must never protect a row whose OWN collection's only manifest row -- points at an agable tombstone. Manifest-less chunks are never swept -- (RDR-145 deferred scope). -- nexus-sybbh: wrapped in a data-modifying CTE (RETURNING chash) so the -- gc_audit row below can name exactly what this call swept, not merely -- how many -- unchanged predicate, byte-identical sweep semantics. WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND m.collection = c.collection AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) ) RETURNING c.chash ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( -- GC_AUDIT_MAX_CHASHES (CatalogRepository.java) = 5000; kept in -- lockstep here since this function writes its own audit row and -- never crosses the JVM boundary to reuse the Java constant. SELECT jsonb_agg(encode(chash, 'hex')) AS s FROM (SELECT chash FROM del LIMIT 5000) lim ) SELECT counted.n, sampled.s INTO v_chunk_count, v_chunk_sample FROM counted, sampled;
-- Step 4: physically delete tombstoned documents older than the threshold. -- fk-001 ON DELETE CASCADE removes catalog_document_chunks, document_aspects, -- document_highlights, and aspect_extraction_queue rows for each deleted doc. -- Unchanged from catalog-026-1 / vectors-005-15. Never joined on collection -- -- catalog_documents carries no collection column (only physical_collection, -- one value per document, not a manifest-row-scoped join key). DELETE FROM nexus.catalog_documents WHERE tenant_id = v_tenant AND deleted_at IS NOT NULL AND deleted_at <= NOW() - older_than;
GET DIAGNOSTICS v_count = ROW_COUNT;
-- nexus-sybbh: audit the reap IN THE SAME TRANSACTION as the deletes -- above (this is still the same implicit function-body transaction; -- nothing has committed yet). Skipped entirely on a genuinely no-op -- call (nothing swept, nothing purged) -- the audit trail records what -- was ACTUALLY reaped, not every invocation. IF v_chunk_count > 0 OR v_count > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( v_tenant, 'purge_trash', '', 'engine', false, COALESCE(v_chunk_count, 0), COALESCE(v_chunk_sample, '[]'::jsonb), jsonb_build_object( 'documents_purged', v_count, 'chunks_swept', COALESCE(v_chunk_count, 0), 'older_than', older_than::text ) || CASE WHEN COALESCE(v_chunk_count, 0) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END ); END IF;
RETURN v_count; END; $function$;

-- =========================================================================================== -- THE WALK'S OWN POST-CONDITIONS. Fail the changeset (and so roll everything back) rather than commit a -- layout that is not what the rest of the engine assumes. -- =========================================================================================== DO $w9$ DECLARE v_parent text; v_bad text; BEGIN FOREACH v_parent IN ARRAY ARRAY['chunks', 'taxonomy_centroids'] LOOP -- RLS on and FORCED on the parent, every model partition and every leaf. SELECT string_agg(c.relname, ', ' ORDER BY c.relname) INTO v_bad FROM pg_catalog.pg_partition_tree(('nexus.' || v_parent)::pg_catalog.regclass) t JOIN pg_catalog.pg_class c ON c.oid = t.relid WHERE NOT (c.relrowsecurity AND c.relforcerowsecurity); IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'vectors-030-1: row-level security is not enabled and forced on: %', v_bad; END IF; -- A leaf for every token tenant and for 'default', under every model partition. SELECT string_agg(pg_catalog.format('%s/%s', mp.relname, tn.tenant_id), ', ') INTO v_bad FROM (SELECT t.tenant_id FROM nexus.service_tokens t UNION SELECT 'default') tn CROSS JOIN (SELECT c.oid, c.relname FROM pg_catalog.pg_inherits i JOIN pg_catalog.pg_class c ON c.oid = i.inhrelid WHERE i.inhparent = ('nexus.' || v_parent)::pg_catalog.regclass) mp WHERE NOT EXISTS (SELECT 1 FROM pg_catalog.pg_inherits j WHERE j.inhparent = mp.oid AND nexus.partition_bound_value(j.inhrelid) = tn.tenant_id); IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'vectors-030-1: no leaf for (model partition/tenant): %', v_bad; END IF; END LOOP;
-- The four foreign keys exist, are validated, and name the four- and three-column keys they should. SELECT string_agg(k.conname, ', ') INTO v_bad FROM (VALUES ('nexus.catalog_document_chunks', 'fk_catalog_chunks_chunk'), ('nexus.topic_assignments', 'topic_assignments_chunk_fk'), ('nexus.chunk_orphaned_at', 'chunk_orphaned_at_chunk_fk'), ('nexus.chunks', 'chunks_collection_fk')) AS want(tbl, con) LEFT JOIN pg_catalog.pg_constraint k ON k.conrelid = want.tbl::pg_catalog.regclass AND k.conname = want.con AND k.contype = 'f' AND k.convalidated WHERE k.oid IS NULL; IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'vectors-030-1: foreign key(s) missing or not validated after the swap: %', v_bad; END IF;
IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_trigger g WHERE g.tgrelid = 'nexus.service_tokens'::pg_catalog.regclass AND g.tgfoid = 'nexus.service_tokens_create_tenant_partitions'::pg_catalog.regproc AND NOT g.tgisinternal) THEN RAISE EXCEPTION 'vectors-030-1: the service_tokens tenant-partition trigger is not attached'; END IF;
-- What the one-transaction walk holds until it commits (sizes max_locks_per_transaction). RAISE LOG 'rdr225 walk: % relation lock(s) held at the end of the walk', (SELECT count(*) FROM pg_catalog.pg_locks l WHERE l.pid = pg_catalog.pg_backend_pid() AND l.locktype = 'relation'); END $w9$;

rollback.sql:
-- ROLLBACK: the inverse of the swap, valid only while nexus.chunks_retired_225 and
-- nexus.taxonomy_centroids_retired_225 still hold the pre-walk tables. It exists to keep the rollback test chain
-- executable (SchemaRollbackRoundTripIntegrationTest rolls older changesets back through a partitioned chunks
-- otherwise, and their forward re-apply adds three-column foreign keys to it). It restores TABLE SHAPE only.
-- It leaves every step 7.8 function body in its post-walk form (they insert embedding_model into a table that no
-- longer has the column), until the rollback of the changeset that last defined each of them runs, and it
-- discards every row written since the walk (those rows live only in the partitioned tables it drops). It is NOT
-- a recovery path. The engine never calls a Liquibase rollback; the recovery for a committed walk is a PITR
-- restore (RDR-225, Failure and rollback).
DO $rb$
DECLARE
    r record;
    a record;
BEGIN
    IF pg_catalog.to_regclass('nexus.chunks_retired_225') IS NULL OR pg_catalog.to_regclass('nexus.taxonomy_centroids_retired_225') IS NULL THEN
        IF (SELECT c.relkind FROM pg_catalog.pg_class c WHERE c.oid = 'nexus.chunks'::pg_catalog.regclass) = 'p' THEN
            RAISE EXCEPTION 'vectors-030-1 rollback: nexus.chunks is partitioned and a retired pre-walk table no longer exists, so the old layout cannot be restored from this database. Restore from a backup taken before the walk.';
        END IF;
        RETURN;
    END IF;

    DROP TRIGGER IF EXISTS trg_service_tokens_create_tenant_partitions ON nexus.service_tokens;

    CREATE TEMP TABLE _p225_views ON COMMIT DROP AS
    SELECT c.relname::text AS view_name,
           pg_catalog.regexp_replace(pg_catalog.pg_get_viewdef(c.oid, true), ';\s*$', '') AS def,
           c.reloptions AS reloptions,
           c.relacl AS relacl,
           c.relowner AS old_owner
      FROM pg_catalog.pg_class c
      JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     WHERE n.nspname = 'nexus' AND c.relkind = 'v'
       AND c.relname IN ('live_chunks', 'collection_vector_stats', 'diag_chash_conformance');
    FOR r IN SELECT v.view_name FROM _p225_views v ORDER BY v.view_name LOOP
        BEGIN
            EXECUTE pg_catalog.format('DROP VIEW nexus.%I', r.view_name);
        EXCEPTION WHEN insufficient_privilege THEN
            RAISE WARNING 'vectors-030-1 rollback: nexus.% is owned by another role and was not dropped', r.view_name;
        END;
    END LOOP;

    ALTER TABLE nexus.catalog_document_chunks DROP CONSTRAINT IF EXISTS fk_catalog_chunks_chunk;
    ALTER TABLE nexus.topic_assignments DROP CONSTRAINT IF EXISTS topic_assignments_chunk_fk;
    ALTER TABLE nexus.chunk_orphaned_at DROP CONSTRAINT IF EXISTS chunk_orphaned_at_chunk_fk;
    ALTER TABLE nexus.catalog_document_chunks DROP COLUMN IF EXISTS embedding_model;
    ALTER TABLE nexus.topic_assignments DROP COLUMN IF EXISTS embedding_model;
    ALTER TABLE nexus.chunk_orphaned_at DROP COLUMN IF EXISTS embedding_model;

    DROP TABLE nexus.chunks;
    DROP TABLE nexus.taxonomy_centroids;
    ALTER TABLE nexus.chunks_retired_225 RENAME TO chunks;
    ALTER TABLE nexus.taxonomy_centroids_retired_225 RENAME TO taxonomy_centroids;
    FOR r IN
        SELECT tc.relname AS tbl, ic.relname AS idx, k.conname AS con
          FROM pg_catalog.pg_index i
          JOIN pg_catalog.pg_class ic ON ic.oid = i.indexrelid
          JOIN pg_catalog.pg_class tc ON tc.oid = i.indrelid
          LEFT JOIN pg_catalog.pg_constraint k ON k.conindid = i.indexrelid AND k.conrelid = i.indrelid
         WHERE i.indrelid IN ('nexus.chunks'::pg_catalog.regclass, 'nexus.taxonomy_centroids'::pg_catalog.regclass)
           AND ic.relname LIKE '%\_retired\_225'
         ORDER BY tc.relname, ic.relname
    LOOP
        IF r.con IS NOT NULL THEN
            EXECUTE pg_catalog.format('ALTER TABLE nexus.%I RENAME CONSTRAINT %I TO %I', r.tbl, r.con,
                                      pg_catalog.regexp_replace(r.con, '_retired_225$', ''));
        ELSE
            EXECUTE pg_catalog.format('ALTER INDEX nexus.%I RENAME TO %I', r.idx,
                                      pg_catalog.regexp_replace(r.idx, '_retired_225$', ''));
        END IF;
    END LOOP;

    -- Adding a foreign key validates it with row-level security applied to the tables the check reads, and the
    -- owner role has no BYPASSRLS, so FORCE is off on them while the keys are added and back on right after.
    ALTER TABLE nexus.chunks NO FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.catalog_collections NO FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.catalog_document_chunks NO FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.topic_assignments NO FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.chunk_orphaned_at NO FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.chunks ADD CONSTRAINT chunks_collection_fk
        FOREIGN KEY (tenant_id, collection) REFERENCES nexus.catalog_collections (tenant_id, name) ON DELETE RESTRICT;
    ALTER TABLE nexus.catalog_document_chunks ADD CONSTRAINT fk_catalog_chunks_chunk
        FOREIGN KEY (tenant_id, collection, chash) REFERENCES nexus.chunks (tenant_id, collection, chash)
        ON UPDATE CASCADE DEFERRABLE INITIALLY IMMEDIATE NOT VALID;
    ALTER TABLE nexus.topic_assignments ADD CONSTRAINT topic_assignments_chunk_fk
        FOREIGN KEY (tenant_id, source_collection, doc_id) REFERENCES nexus.chunks (tenant_id, collection, chash)
        ON UPDATE CASCADE ON DELETE CASCADE NOT VALID;
    ALTER TABLE nexus.chunk_orphaned_at ADD CONSTRAINT chunk_orphaned_at_chunk_fk
        FOREIGN KEY (tenant_id, collection, chash) REFERENCES nexus.chunks (tenant_id, collection, chash)
        ON UPDATE CASCADE ON DELETE CASCADE NOT VALID;
    -- Validate when the rows allow it. A row written after the walk may not satisfy the old keys; that leaves
    -- the key NOT VALID (still enforced for every later write) instead of failing the rollback.
    FOR r IN
        SELECT * FROM (VALUES ('catalog_document_chunks', 'fk_catalog_chunks_chunk'),
                              ('topic_assignments', 'topic_assignments_chunk_fk'),
                              ('chunk_orphaned_at', 'chunk_orphaned_at_chunk_fk')) AS t(tbl, con)
    LOOP
        BEGIN
            EXECUTE pg_catalog.format('ALTER TABLE nexus.%I VALIDATE CONSTRAINT %I', r.tbl, r.con);
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE WARNING 'vectors-030-1 rollback: %.% left NOT VALID (a row does not satisfy the three-column key)', r.tbl, r.con;
        END;
    END LOOP;

    ALTER TABLE nexus.chunks FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.catalog_collections FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.catalog_document_chunks FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.topic_assignments FORCE ROW LEVEL SECURITY;
    ALTER TABLE nexus.chunk_orphaned_at FORCE ROW LEVEL SECURITY;

    FOR r IN SELECT v.view_name, v.def, v.reloptions, v.relacl, v.old_owner FROM _p225_views v
                  WHERE pg_catalog.to_regclass('nexus.' || pg_catalog.quote_ident(v.view_name)) IS NULL
                  ORDER BY v.view_name LOOP
        EXECUTE pg_catalog.format('CREATE VIEW nexus.%I%s AS %s', r.view_name,
                                  CASE WHEN r.reloptions IS NULL THEN ''
                                       ELSE ' WITH (' || pg_catalog.array_to_string(r.reloptions, ', ') || ')' END,
                                  r.def);
        IF r.relacl IS NOT NULL THEN
            FOR a IN
                SELECT x.grantee, x.privilege_type, x.is_grantable
                  FROM pg_catalog.aclexplode(r.relacl) x
                 WHERE x.grantee <> (SELECT c.relowner FROM pg_catalog.pg_class c WHERE c.oid = ('nexus.' || pg_catalog.quote_ident(r.view_name))::pg_catalog.regclass)
                   AND x.grantee <> r.old_owner
                 ORDER BY x.grantee, x.privilege_type
            LOOP
                EXECUTE pg_catalog.format('GRANT %s ON nexus.%I TO %s%s', a.privilege_type, r.view_name,
                    CASE WHEN a.grantee = 0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END,
                    CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END);
            END LOOP;
        END IF;
    END LOOP;
END
$rb$;
